{
  "name": "Lumina Puzzle Master",
  "description": "An advanced sliding puzzle game with custom image support, multiple grid sizes, automated solving, and game state persistence.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export type GridSize = {
  rows: number;
  cols: number;
};

export type Difficulty = 'Easy' | 'Medium' | 'Hard';

export interface GameState {
  board: number[];
  moves: number;
  seconds: number;
  imageUrl: string;
  gridSize: GridSize;
  history: number[][];
  difficulty: Difficulty;
  spacing: number;
}

export interface StatsEntry {
  date: string;
  moves: number;
  time: number;
  gridSize: string;
}

export interface PuzzleContextType {
  state: GameState;
  isSolved: boolean;
  isSolving: boolean;
  highlightedTile: number | null;
  clueTile: number | null;
  moveTile: (index: number) => void;
  shuffle: () => void;
  solve: () => void;
  clue: () => void;
  undo: () => void;
  updateGrid: (rows: number, cols: number) => void;
  updateImageUrl: (url: string) => void;
  updateDifficulty: (d: Difficulty) => void;
  updateSpacing: (s: number) => void;
  resetGame: () => void;
  loadSavedGame: () => void;
  saveGame: () => void;
}

import { GridSize } from '../types';

export const isAdjacent = (idx1: number, idx2: number, size: GridSize): boolean => {
  const r1 = Math.floor(idx1 / size.cols);
  const c1 = idx1 % size.cols;
  const r2 = Math.floor(idx2 / size.cols);
  const c2 = idx2 % size.cols;
  return Math.abs(r1 - r2) + Math.abs(c1 - c2) === 1;
};

export const getMovableIndices = (emptyIdx: number, size: GridSize): number[] => {
  const movables: number[] = [];
  const r = Math.floor(emptyIdx / size.cols);
  const c = emptyIdx % size.cols;

  if (r > 0) movables.push(emptyIdx - size.cols);
  if (r < size.rows - 1) movables.push(emptyIdx + size.cols);
  if (c > 0) movables.push(emptyIdx - 1);
  if (c < size.cols - 1) movables.push(emptyIdx + 1);

  return movables;
};

export const isSolved = (board: number[]): boolean => {
  for (let i = 0; i < board.length - 1; i++) {
    if (board[i] !== i) return false;
  }
  return true;
};

// Simple Manhattan distance heuristic for A* (limited search for performance)
export const getManhattanDistance = (board: number[], size: GridSize): number => {
  let distance = 0;
  for (let i = 0; i < board.length; i++) {
    const val = board[i];
    if (val === board.length - 1) continue; // Skip empty tile
    const currentR = Math.floor(i / size.cols);
    const currentC = i % size.cols;
    const targetR = Math.floor(val / size.cols);
    const targetC = val % size.cols;
    distance += Math.abs(currentR - targetR) + Math.abs(currentC - targetC);
  }
  return distance;
};

// Since full A* for 15-puzzle (4x4) is computationally expensive in JS for a single frame,
// we often use IDA* or simply store the shuffle path. 
// For this app, to provide a "Solve" button that moves one by one, 
// we will implement a simple Greedy Best-First Search for small depths 
// or rely on a recorded shuffle history to reverse.

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, GridSize, Difficulty, StatsEntry } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/800/800?random=1';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [spacing, setSpacing] = useState(2);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [highlightedTile, setHighlightedTile] = useState<number | null>(null);
  const [clueTile, setClueTile] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [imageHistory, setImageHistory] = useState<string[]>([]);

  const timerRef = useRef<number | null>(null);
  const solveSequenceRef = useRef<number[]>([]);

  // Initialize board
  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setHistory([]);
    setIsGameFinished(false);
    setClueTile(null);
  }, []);

  useEffect(() => {
    initBoard(gridSize);
    // Load image history
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) setImageHistory(JSON.parse(storedHistory));
  }, [gridSize, initBoard]);

  // Timer logic
  useEffect(() => {
    if (moves > 0 && !isGameFinished && !isSolving) {
      timerRef.current = window.setInterval(() => {
        setSeconds(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [moves, isGameFinished, isSolving]);

  const moveTile = (index: number, silent = false) => {
    if (isSolving && !silent) return;
    const emptyIdx = board.indexOf(board.length - 1);
    if (isAdjacent(index, emptyIdx, gridSize)) {
      const newBoard = [...board];
      [newBoard[index], newBoard[emptyIdx]] = [newBoard[emptyIdx], newBoard[index]];

      setHistory(prev => [...prev, [...board]]);
      setBoard(newBoard);
      setMoves(prev => prev + 1);
      setClueTile(null);

      if (!silent && isSolved(newBoard)) {
        setIsGameFinished(true);
        saveToStats(moves + 1, seconds, gridSize);
      }
    }
  };

  const saveToStats = (moves: number, time: number, size: GridSize) => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const newEntry: StatsEntry = {
      date: new Date().toLocaleDateString(),
      moves,
      time,
      gridSize: `${size.rows}x${size.cols}`
    };
    const updatedStats = [newEntry, ...stats].slice(0, 10);
    localStorage.setItem('puzzle_stats', JSON.stringify(updatedStats));
  };

  const shuffle = () => {
    let newBoard = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    let shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let currentBoard = [...newBoard];
    let lastEmpty = -1;

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = currentBoard.indexOf(currentBoard.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      [currentBoard[emptyIdx], currentBoard[move]] = [currentBoard[move], currentBoard[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setBoard(currentBoard);
    setMoves(0);
    setSeconds(0);
    setHistory([]);
    setIsGameFinished(false);
  };

  const undo = () => {
    if (history.length === 0) return;
    const prevBoard = history[history.length - 1];
    setBoard(prevBoard);
    setHistory(prev => prev.slice(0, -1));
    setMoves(prev => Math.max(0, prev - 1));
  };

  const clue = () => {
    const emptyIdx = board.indexOf(board.length - 1);
    const movables = getMovableIndices(emptyIdx, gridSize);
    // Simple heuristic: which move brings us closer to solved?
    // For now, pick a random valid move as a 'legal' clue.
    const randomMovable = movables[Math.floor(Math.random() * movables.length)];
    setClueTile(randomMovable);
  };

  const solve = async () => {
    if (isSolving) return;
    setIsSolving(true);

    // For the demonstration, we'll reverse the move history if available, 
    // or perform a simple search. Since history might be manually altered, 
    // a real solver would be better, but it's complex for 15-puzzle.
    // Instead, we use the recorded history as the most reliable "path home".
    const path = [...history].reverse();

    for (const stepBoard of path) {
      // Find what moved
      const emptyIdxNow = board.indexOf(board.length - 1);
      const emptyIdxNext = stepBoard.indexOf(stepBoard.length - 1);

      setHighlightedTile(emptyIdxNext);
      await new Promise(r => setTimeout(r, 1000));
      setBoard(stepBoard);
      setMoves(prev => prev + 1);
      setHighlightedTile(null);
    }

    setIsSolving(false);
    setIsGameFinished(true);
  };

  const saveGame = () => {
    const data = { board, moves, seconds, imageUrl, gridSize, history, difficulty, spacing };
    localStorage.setItem('puzzle_saved_game', JSON.stringify(data));
    alert('Game Saved!');
  };

  const loadSavedGame = () => {
    const data = localStorage.getItem('puzzle_saved_game');
    if (data) {
      const parsed = JSON.parse(data);
      setBoard(parsed.board);
      setMoves(parsed.moves);
      setSeconds(parsed.seconds);
      setImageUrl(parsed.imageUrl);
      setGridSize(parsed.gridSize);
      setHistory(parsed.history);
      setDifficulty(parsed.difficulty);
      setSpacing(parsed.spacing);
      setIsMenuOpen(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const url = ev.target?.result as string;
        setImageUrl(url);
        const newHistory = [url, ...imageHistory.filter(i => i !== url)].slice(0, 5);
        setImageHistory(newHistory);
        localStorage.setItem('puzzle_image_history', JSON.stringify(newHistory));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative bg-slate-950 text-white overflow-hidden">
      {/* 3-Dot Menu Button */}
      <button 
        onClick={() => setIsMenuOpen(true)}
        className="absolute top-6 left-6 p-2 rounded-full bg-slate-800/50 hover:bg-slate-700 transition-colors z-40"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
      </button>

      {/* Stats Bar */}
      <div className="mb-6 flex space-x-8 text-sm font-medium tracking-wider uppercase text-slate-400">
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">{moves}</span>
          <span>Moves</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">
            {Math.floor(seconds / 60)}:{(seconds % 60).toString().padStart(2, '0')}
          </span>
          <span>Time</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">{gridSize.rows}x{gridSize.cols}</span>
          <span>Grid</span>
        </div>
      </div>

      {/* Puzzle Board Area */}
      <div className="flex-1 flex items-center justify-center w-full max-w-2xl">
        <PuzzleBoard 
          board={board} 
          gridSize={gridSize} 
          imageUrl={imageUrl} 
          onTileClick={moveTile} 
          spacing={spacing}
          highlightedTile={highlightedTile}
          clueTile={clueTile}
        />
      </div>

      {/* Controls */}
      <div className="mt-8 w-full max-w-lg">
        <Controls 
          onShuffle={shuffle}
          onSolve={solve}
          onClue={clue}
          onUndo={undo}
          isSolving={isSolving}
        />
      </div>

      {/* Modals & Overlays */}
      {isGameFinished && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 border border-slate-800 p-8 rounded-2xl max-w-sm w-full text-center shadow-2xl">
            <h2 className="text-3xl font-bold mb-2">Solved!</h2>
            <p className="text-slate-400 mb-6">You finished in {moves} moves and {seconds} seconds.</p>
            <div className="space-y-3">
              <button 
                onClick={() => {
                  initBoard(gridSize);
                  shuffle();
                }}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-semibold transition-colors"
              >
                Play Again
              </button>
              <button 
                onClick={() => setIsGameFinished(false)}
                className="w-full py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-semibold transition-colors"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <Menu 
        isOpen={isMenuOpen} 
        onClose={() => setIsMenuOpen(false)}
        gridSize={gridSize}
        setGridSize={setGridSize}
        difficulty={difficulty}
        setDifficulty={setDifficulty}
        spacing={spacing}
        setSpacing={setSpacing}
        onImageUpload={handleImageUpload}
        imageHistory={imageHistory}
        onSelectHistoryImage={setImageUrl}
        onSave={saveGame}
        onLoad={loadSavedGame}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { GridSize } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  highlightedTile: number | null;
  clueTile: number | null;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = ({ 
  board, 
  gridSize, 
  imageUrl, 
  onTileClick, 
  spacing,
  highlightedTile,
  clueTile
}) => {
  const containerWidth = 400; // Fixed max width for visual consistency
  const tileWidth = (containerWidth - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileHeight = tileWidth; // Square tiles for simplicity

  return (
    <div 
      className="relative bg-slate-900/50 p-2 rounded-xl shadow-inner border border-white/5 overflow-hidden"
      style={{
        width: containerWidth + 16,
        height: (tileHeight * gridSize.rows) + (spacing * (gridSize.rows - 1)) + 16,
      }}
    >
      {board.map((tileValue, currentIndex) => {
        if (tileValue === board.length - 1) return null;

        const row = Math.floor(currentIndex / gridSize.cols);
        const col = currentIndex % gridSize.cols;

        const originalRow = Math.floor(tileValue / gridSize.cols);
        const originalCol = tileValue % gridSize.cols;

        const posX = col * (tileWidth + spacing);
        const posY = row * (tileHeight + spacing);

        const bgPosX = (originalCol / (gridSize.cols - 1)) * 100;
        const bgPosY = (originalRow / (gridSize.rows - 1)) * 100;

        const isHighlighted = highlightedTile === currentIndex;
        const isClue = clueTile === currentIndex;

        return (
          <div
            key={tileValue}
            onClick={() => onTileClick(currentIndex)}
            className="absolute puzzle-tile-transition cursor-pointer rounded-lg overflow-hidden group shadow-lg"
            style={{
              width: tileWidth,
              height: tileHeight,
              left: posX + 8,
              top: posY + 8,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${bgPosX}% ${bgPosY}%`,
            }}
          >
            {/* Tile Border Overlay */}
            <div className="absolute inset-0 border border-white/10 group-hover:border-white/30 transition-colors" />

            {/* Highlight (Solving) */}
            {isHighlighted && (
              <div className="absolute inset-0 flex items-center justify-center bg-yellow-400/20">
                <div className="w-12 h-12 rounded-full border-4 border-yellow-400 animate-ping opacity-75" />
                <div className="w-8 h-8 rounded-full bg-yellow-400 absolute shadow-2xl" />
              </div>
            )}

            {/* Clue Dot */}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center">
                <div className="w-4 h-4 rounded-full bg-yellow-400 shadow-[0_0_15px_rgba(250,204,21,0.8)] clue-dot" />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

export default PuzzleBoard;

import React from 'react';

interface ControlsProps {
  onShuffle: () => void;
  onSolve: () => void;
  onClue: () => void;
  onUndo: () => void;
  isSolving: boolean;
}

const Controls: React.FC<ControlsProps> = ({ onShuffle, onSolve, onClue, onUndo, isSolving }) => {
  return (
    <div className="grid grid-cols-2 md:grid-cols-4 gap-4">
      <button
        onClick={onShuffle}
        disabled={isSolving}
        className="flex flex-col items-center justify-center p-4 rounded-2xl bg-slate-800/80 hover:bg-slate-700/80 border border-white/5 transition-all active:scale-95 disabled:opacity-50"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mb-2"><path d="M2 18h1.4c1.3 0 2.5-.6 3.3-1.7l6.1-8.6c.7-1.1 2-1.7 3.3-1.7H22"/><path d="m18 2 4 4-4 4"/><path d="M2 6h1.9c1.5 0 2.9.9 3.6 2.2"/><path d="M22 18h-5.9c-1.3 0-2.6-.7-3.3-1.8l-.5-.8"/><path d="m18 14 4 4-4 4"/></svg>
        <span className="text-xs font-bold uppercase tracking-widest">Shuffle</span>
      </button>

      <button
        onClick={onSolve}
        disabled={isSolving}
        className="flex flex-col items-center justify-center p-4 rounded-2xl bg-indigo-600/80 hover:bg-indigo-500/80 border border-indigo-400/20 transition-all active:scale-95 disabled:opacity-50"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mb-2"><path d="m12 14 4-4"/><path d="M3.34 19a10 10 0 1 1 17.32 0"/></svg>
        <span className="text-xs font-bold uppercase tracking-widest">{isSolving ? 'Solving...' : 'Solve'}</span>
      </button>

      <button
        onClick={onClue}
        disabled={isSolving}
        className="flex flex-col items-center justify-center p-4 rounded-2xl bg-yellow-600/20 hover:bg-yellow-600/30 border border-yellow-400/20 text-yellow-400 transition-all active:scale-95 disabled:opacity-50"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mb-2"><circle cx="12" cy="12" r="10"/><path d="M9.09 9a3 3 0 0 1 5.83 1c0 2-3 3-3 3"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>
        <span className="text-xs font-bold uppercase tracking-widest">Clue</span>
      </button>

      <button
        onClick={onUndo}
        disabled={isSolving}
        className="flex flex-col items-center justify-center p-4 rounded-2xl bg-slate-800/80 hover:bg-slate-700/80 border border-white/5 transition-all active:scale-95 disabled:opacity-50"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mb-2"><path d="M3 10h10a8 8 0 0 1 8 8v2"/><path d="m3 10 7-7"/><path d="m3 10 7 7"/></svg>
        <span className="text-xs font-bold uppercase tracking-widest">Undo</span>
      </button>
    </div>
  );
};

export default Controls;

import React from 'react';
import { GridSize, Difficulty, StatsEntry } from '../types';

interface MenuProps {
  isOpen: boolean;
  onClose: () => void;
  gridSize: GridSize;
  setGridSize: (g: GridSize) => void;
  difficulty: Difficulty;
  setDifficulty: (d: Difficulty) => void;
  spacing: number;
  setSpacing: (s: number) => void;
  onImageUpload: (e: React.ChangeEvent<HTMLInputElement>) => void;
  imageHistory: string[];
  onSelectHistoryImage: (url: string) => void;
  onSave: () => void;
  onLoad: () => void;
}

const Menu: React.FC<MenuProps> = ({
  isOpen, onClose, gridSize, setGridSize, difficulty, setDifficulty, 
  spacing, setSpacing, onImageUpload, imageHistory, onSelectHistoryImage,
  onSave, onLoad
}) => {
  if (!isOpen) return null;

  const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');

  return (
    <div className="fixed inset-0 z-50 flex">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-full max-w-sm bg-slate-900 border-r border-white/10 h-full overflow-y-auto p-8 shadow-2xl flex flex-col space-y-8 animate-slide-in">
        <div className="flex justify-between items-center">
          <h2 className="text-2xl font-bold text-white">Settings</h2>
          <button onClick={onClose} className="p-2 hover:bg-white/10 rounded-full transition-colors">
            <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
          </button>
        </div>

        {/* Persistence */}
        <section className="space-y-4">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">State Management</h3>
          <div className="flex gap-2">
            <button onClick={onSave} className="flex-1 py-2 bg-blue-600/20 border border-blue-400/30 text-blue-400 rounded-lg text-sm hover:bg-blue-600/30 transition-colors">Save Game</button>
            <button onClick={onLoad} className="flex-1 py-2 bg-slate-800 border border-white/10 text-white rounded-lg text-sm hover:bg-slate-700 transition-colors">Load Game</button>
          </div>
        </section>

        {/* Grid Selection */}
        <section className="space-y-4">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Select Grid</h3>
          <div className="grid grid-cols-3 gap-2">
            {[ {r:3, c:3}, {r:4, c:4}, {r:5, c:4} ].map(g => (
              <button 
                key={`${g.r}x${g.c}`}
                onClick={() => setGridSize({rows: g.r, cols: g.c})}
                className={`py-2 rounded-lg text-sm font-medium border transition-all ${
                  gridSize.rows === g.r && gridSize.cols === g.c 
                  ? 'bg-blue-600 border-blue-400 text-white' 
                  : 'bg-slate-800 border-white/5 text-slate-400 hover:text-white'
                }`}
              >
                {g.r}x{g.c}
              </button>
            ))}
          </div>
        </section>

        {/* Difficulty */}
        <section className="space-y-4">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Difficulty</h3>
          <div className="flex space-x-2">
            {(['Easy', 'Medium', 'Hard'] as Difficulty[]).map(d => (
              <button 
                key={d}
                onClick={() => setDifficulty(d)}
                className={`flex-1 py-2 rounded-lg text-sm transition-all ${
                  difficulty === d 
                  ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-500/20' 
                  : 'bg-slate-800 text-slate-400'
                }`}
              >
                {d}
              </button>
            ))}
          </div>
        </section>

        {/* Spacing Slider */}
        <section className="space-y-4">
          <div className="flex justify-between items-center">
            <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Tile Spacing</h3>
            <span className="text-xs text-blue-400 font-mono">{spacing}px</span>
          </div>
          <input 
            type="range" min="0" max="10" step="1" 
            value={spacing} onChange={(e) => setSpacing(parseInt(e.target.value))}
            className="w-full h-2 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-600"
          />
        </section>

        {/* Image Handling */}
        <section className="space-y-4">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Pick Picture</h3>
          <label className="block">
            <span className="sr-only">Choose image</span>
            <input type="file" onChange={onImageUpload} accept="image/*" className="block w-full text-sm text-slate-500 file:mr-4 file:py-2 file:px-4 file:rounded-full file:border-0 file:text-sm file:font-semibold file:bg-blue-600/10 file:text-blue-400 hover:file:bg-blue-600/20 cursor-pointer"/>
          </label>

          {imageHistory.length > 0 && (
            <div className="pt-2">
              <h4 className="text-[10px] font-bold text-slate-600 uppercase mb-2">Recent Images</h4>
              <div className="flex gap-2 overflow-x-auto pb-2">
                {imageHistory.map((url, idx) => (
                  <button 
                    key={idx} 
                    onClick={() => onSelectHistoryImage(url)}
                    className="w-16 h-16 rounded-lg bg-cover bg-center shrink-0 border border-white/10 hover:border-blue-500 transition-colors shadow-lg"
                    style={{ backgroundImage: `url(${url})` }}
                  />
                ))}
              </div>
            </div>
          )}
        </section>

        {/* Stats */}
        <section className="space-y-4 pb-8">
          <h3 className="text-xs font-bold text-slate-500 uppercase tracking-widest">Best Games (Last 10)</h3>
          {stats.length === 0 ? (
            <p className="text-sm text-slate-600 italic">No games finished yet.</p>
          ) : (
            <div className="space-y-2">
              {stats.map((s, i) => (
                <div key={i} className="flex justify-between items-center text-xs p-3 rounded-lg bg-slate-800/50 border border-white/5">
                  <span className="text-slate-400">{s.date}</span>
                  <span className="font-bold text-blue-400">{s.gridSize}</span>
                  <div className="flex gap-3">
                    <span className="text-white">{s.moves}m</span>
                    <span className="text-slate-500">{s.time}s</span>
                  </div>
                </div>
              ))}
            </div>
          )}
        </section>
      </div>
    </div>
  );
};

export default Menu;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GameState, GridSize, Difficulty, StatsEntry } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/800/800?random=1';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [spacing, setSpacing] = useState(2);
  const [spacingColor, setSpacingColor] = useState('transparent');
  const [showNumbers, setShowNumbers] = useState(false);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [highlightedTile, setHighlightedTile] = useState<number | null>(null);
  const [clueTile, setClueTile] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [imageHistory, setImageHistory] = useState<string[]>([]);

  const timerRef = useRef<number | null>(null);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setHistory([]);
    setIsGameFinished(false);
    setClueTile(null);
  }, []);

  useEffect(() => {
    initBoard(gridSize);
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) setImageHistory(JSON.parse(storedHistory));
  }, [gridSize, initBoard]);

  useEffect(() => {
    if (moves > 0 && !isGameFinished && !isSolving) {
      timerRef.current = window.setInterval(() => {
        setSeconds(prev => prev + 1);
      }, 1000);
    } else {
      if (timerRef.current) clearInterval(timerRef.current);
    }
    return () => {
      if (timerRef.current) clearInterval(timerRef.current);
    };
  }, [moves, isGameFinished, isSolving]);

  const moveTile = (index: number, silent = false) => {
    if (isSolving && !silent) return;
    const emptyIdx = board.indexOf(board.length - 1);
    if (isAdjacent(index, emptyIdx, gridSize)) {
      const newBoard = [...board];
      [newBoard[index], newBoard[emptyIdx]] = [newBoard[emptyIdx], newBoard[index]];

      setHistory(prev => [...prev, [...board]]);
      setBoard(newBoard);
      setMoves(prev => prev + 1);
      setClueTile(null);

      if (!silent && isSolved(newBoard)) {
        setIsGameFinished(true);
        saveToStats(moves + 1, seconds, gridSize);
      }
    }
  };

  const saveToStats = (moves: number, time: number, size: GridSize) => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const newEntry: StatsEntry = {
      date: new Date().toLocaleDateString(),
      moves,
      time,
      gridSize: `${size.rows}x${size.cols}`
    };
    const updatedStats = [newEntry, ...stats].slice(0, 10);
    localStorage.setItem('puzzle_stats', JSON.stringify(updatedStats));
  };

  const shuffle = () => {
    if (isSolving) return;
    let currentBoard = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    let shuffleCount = difficulty === 'Easy' ? 15 : difficulty === 'Medium' ? 40 : 100;
    let lastEmpty = -1;
    let tempHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = currentBoard.indexOf(currentBoard.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];

      tempHistory.push([...currentBoard]);
      [currentBoard[emptyIdx], currentBoard[move]] = [currentBoard[move], currentBoard[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setBoard(currentBoard);
    setMoves(0);
    setSeconds(0);
    setHistory(tempHistory);
    setIsGameFinished(false);
    setClueTile(null);
  };

  const undo = () => {
    if (history.length === 0 || isSolving) return;
    const prevBoard = history[history.length - 1];
    setBoard(prevBoard);
    setHistory(prev => prev.slice(0, -1));
    setMoves(prev => Math.max(0, prev - 1));
    setClueTile(null);
  };

  const clue = () => {
    if (isSolving || isGameFinished) return;
    const emptyIdx = board.indexOf(board.length - 1);
    const movables = getMovableIndices(emptyIdx, gridSize);
    // Suggest a random valid move
    const randomMovable = movables[Math.floor(Math.random() * movables.length)];
    setClueTile(randomMovable);
  };

  const solve = async () => {
    if (isSolving || isSolved(board)) {
      if (isSolved(board)) setIsGameFinished(true);
      return;
    }
    setIsSolving(true);
    setClueTile(null);

    // Play back history in reverse to solve
    const path = [...history].reverse();

    for (const stepBoard of path) {
      // Find the tile that is about to move into the empty space
      const currentEmptyIdx = board.indexOf(board.length - 1);
      const targetEmptyIdx = stepBoard.indexOf(stepBoard.length - 1);

      setHighlightedTile(targetEmptyIdx);
      await new Promise(r => setTimeout(r, 1000));

      setBoard(stepBoard);
      setMoves(prev => prev + 1);
      setHighlightedTile(null);

      // If for some reason we already reached solved state (user moved pieces manually)
      if (isSolved(stepBoard)) break;
    }

    setIsSolving(false);
    if (isSolved(board)) {
      setIsGameFinished(true);
    }
  };

  const saveGame = () => {
    const data = { board, moves, seconds, imageUrl, gridSize, history, difficulty, spacing, spacingColor, showNumbers };
    localStorage.setItem('puzzle_saved_game', JSON.stringify(data));
    alert('Game Saved!');
  };

  const loadSavedGame = () => {
    const data = localStorage.getItem('puzzle_saved_game');
    if (data) {
      const parsed = JSON.parse(data);
      setBoard(parsed.board);
      setMoves(parsed.moves);
      setSeconds(parsed.seconds);
      setImageUrl(parsed.imageUrl);
      setGridSize(parsed.gridSize);
      setHistory(parsed.history);
      setDifficulty(parsed.difficulty);
      setSpacing(parsed.spacing);
      setSpacingColor(parsed.spacingColor || 'transparent');
      setShowNumbers(parsed.showNumbers || false);
      setIsMenuOpen(false);
      setIsGameFinished(false);
    }
  };

  const handleImageUpload = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const url = ev.target?.result as string;
        setImageUrl(url);
        const newHistory = [url, ...imageHistory.filter(i => i !== url)].slice(0, 5);
        setImageHistory(newHistory);
        localStorage.setItem('puzzle_image_history', JSON.stringify(newHistory));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="min-h-screen flex flex-col items-center justify-center p-4 relative bg-slate-950 text-white overflow-hidden">
      <button 
        onClick={() => setIsMenuOpen(true)}
        className="absolute top-6 left-6 p-2 rounded-full bg-slate-800/50 hover:bg-slate-700 transition-colors z-40"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
      </button>

      <div className="mb-6 flex space-x-8 text-sm font-medium tracking-wider uppercase text-slate-400">
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">{moves}</span>
          <span>Moves</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">
            {Math.floor(seconds / 60)}:{(seconds % 60).toString().padStart(2, '0')}
          </span>
          <span>Time</span>
        </div>
        <div className="flex flex-col items-center">
          <span className="text-2xl text-white font-bold">{gridSize.rows}x{gridSize.cols}</span>
          <span>Grid</span>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center w-full max-w-2xl">
        <PuzzleBoard 
          board={board} 
          gridSize={gridSize} 
          imageUrl={imageUrl} 
          onTileClick={moveTile} 
          spacing={spacing}
          spacingColor={spacingColor}
          showNumbers={showNumbers}
          highlightedTile={highlightedTile}
          clueTile={clueTile}
        />
      </div>

      <div className="mt-8 w-full max-w-lg">
        <Controls 
          onShuffle={shuffle}
          onSolve={solve}
          onClue={clue}
          onUndo={undo}
          isSolving={isSolving}
        />
      </div>

      {isGameFinished && (
        <div className="fixed inset-0 bg-slate-950/90 backdrop-blur-md flex items-center justify-center z-50 p-6">
          <div className="bg-slate-900 border border-slate-800 p-8 rounded-2xl max-w-sm w-full text-center shadow-2xl">
            <h2 className="text-3xl font-bold mb-2">Solved!</h2>
            <p className="text-slate-400 mb-6">You finished in {moves} moves and {seconds} seconds.</p>
            <div className="space-y-3">
              <button 
                onClick={() => {
                  initBoard(gridSize);
                  shuffle();
                }}
                className="w-full py-3 bg-blue-600 hover:bg-blue-500 rounded-xl font-semibold transition-colors"
              >
                Play Again
              </button>
              <button 
                onClick={() => setIsGameFinished(false)}
                className="w-full py-3 bg-slate-800 hover:bg-slate-700 rounded-xl font-semibold transition-colors"
              >
                Close
              </button>
            </div>
          </div>
        </div>
      )}

      <Menu 
        isOpen={isMenuOpen} 
        onClose={() => setIsMenuOpen(false)}
        gridSize={gridSize}
        setGridSize={setGridSize}
        difficulty={difficulty}
        setDifficulty={setDifficulty}
        spacing={spacing}
        setSpacing={setSpacing}
        spacingColor={spacingColor}
        setSpacingColor={setSpacingColor}
        showNumbers={showNumbers}
        setShowNumbers={setShowNumbers}
        onImageUpload={handleImageUpload}
        imageHistory={imageHistory}
        onSelectHistoryImage={setImageUrl}
        onSave={saveGame}
        onLoad={loadSavedGame}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { GridSize } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  spacingColor: string;
  showNumbers: boolean;
  highlightedTile: number | null;
  clueTile: number | null;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = ({ 
  board, 
  gridSize, 
  imageUrl, 
  onTileClick, 
  spacing,
  spacingColor,
  showNumbers,
  highlightedTile,
  clueTile
}) => {
  const containerWidth = 400; 
  const tileWidth = (containerWidth - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileHeight = tileWidth; 

  const boardStyle = {
    width: containerWidth + 16,
    height: (tileHeight * gridSize.rows) + (spacing * (gridSize.rows - 1)) + 16,
    backgroundColor: spacingColor === 'auto' ? 'rgba(255,255,255,0.05)' : spacingColor
  };

  return (
    <div 
      className="relative p-2 rounded-xl shadow-inner border border-white/5 overflow-hidden transition-colors duration-500"
      style={boardStyle}
    >
      {board.map((tileValue, currentIndex) => {
        if (tileValue === board.length - 1) return null;

        const row = Math.floor(currentIndex / gridSize.cols);
        const col = currentIndex % gridSize.cols;

        const originalRow = Math.floor(tileValue / gridSize.cols);
        const originalCol = tileValue % gridSize.cols;

        const posX = col * (tileWidth + spacing);
        const posY = row * (tileHeight + spacing);

        const bgPosX = (originalCol / (gridSize.cols - 1)) * 100;
        const bgPosY = (originalRow / (gridSize.rows - 1)) * 100;

        const isHighlighted = highlightedTile === currentIndex;
        const isClue = clueTile === currentIndex;

        return (
          <div
            key={tileValue}
            onClick={() => onTileClick(currentIndex)}
            className="absolute puzzle-tile-transition cursor-pointer rounded-lg overflow-hidden group shadow-lg"
            style={{
              width: tileWidth,
              height: tileHeight,
              left: posX + 8,
              top: posY + 8,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${bgPosX}% ${bgPosY}%`,
            }}
          >
            {/* Tile Border Overlay */}
            <div className="absolute inset-0 border border-white/10 group-hover:border-white/30 transition-colors" />

            {/* Tile Number */}
            {showNumbers && (
              <div className="absolute top-1 left-1 px-1.5 py-0.5 bg-black/40 backdrop-blur-sm rounded text-[10px] font-bold text-white border border-white/10 select-none">
                {tileValue + 1}
              </div>
            )}

            {/* Highlight (Solving) */}
            {isHighlighted && (
              <div className="absolute inset-0 flex items-center justify-center bg-yellow-400/20">
                <div className="w-12 h-12 rounded-full border-4 border-yellow-400 animate-ping opacity-75" />
                <div className="w-8 h-8 rounded-full bg-yellow-400 absolute shadow-2xl" />
              </div>
            )}

            {/* Clue Dot */}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none">
                <div className="w-4 h-4 rounded-full bg-yellow-400 shadow-[0_0_15px_rgba(250,204,21,0.8)] clue-dot" />
              </div>
            )}
          </div>
        );
      })}
    </div>
  );
};

