                        className={`flex-1 py-2 rounded-xl text-xs font-bold transition-all border ${
                            difficulty === d 
                            ? 'bg-indigo-600 border-indigo-400' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {d}
                    </button>
                ))}
            </div>
        </section>

        {/* Spacing */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Tile Spacing</h3>
            <input 
                type="range" min="0" max="10" 
                value={spacing} onChange={(e) => setSpacing(parseInt(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
            />
        </section>

        {/* Stats */}
        <section className="mt-auto">
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Stats (Best 10)</h3>
            <div className="space-y-2">
                {stats.length === 0 ? (
                    <p className="text-[10px] text-slate-600 italic">No games finished yet.</p>
                ) : (
                    stats.map((s, i) => (
                        <div key={i} className="flex justify-between items-center bg-slate-800/50 p-2 rounded-lg text-[10px]">
                            <span className="font-bold">{s.gridSize}</span>
                            <span className="text-blue-400">{s.moves} moves</span>
                            <span className="text-slate-500">{s.time}s</span>
                        </div>
                    ))
                )}
            </div>
        </section>
      </div>
    </div>
  );
};

export default Menu;

{
  "name": "lumina-puzzle-master",
  "version": "1.1.0",
  "description": "Advanced sliding puzzle with AI image generation and state persistence",
  "dependencies": {
    "@google/genai": "^0.21.0",
    "react": "^19.0.0",
    "react-dom": "^19.0.0"
  },
  "devDependencies": {
    "@types/react": "^19.0.0",
    "@types/react-dom": "^19.0.0",
    "typescript": "^5.7.0"
  }
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GoogleGenAI } from "@google/genai";
import { GridSize, Difficulty, StatsEntry } from './types';
import { isAdjacent, getMovableIndices, isSolved, getManhattanDistance } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/800/800?random=42';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [distance, setDistance] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [spacing, setSpacing] = useState(2);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);

  const historyRef = useRef<number[][]>([]);
  const timerRef = useRef<number | null>(null);
  const abortSolvingRef = useRef(false);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setDistance(0);
    historyRef.current = [];
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
  }, []);

  useEffect(() => {
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) setImageHistory(JSON.parse(storedHistory));

    const lastState = localStorage.getItem('puzzle_current_state');
    if (lastState) {
        try {
            const parsed = JSON.parse(lastState);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setSeconds(parsed.seconds);
            setImageUrl(parsed.imageUrl);
            setGridSize(parsed.gridSize);
            historyRef.current = parsed.history || [];
            setDifficulty(parsed.difficulty || 'Medium');
            setSpacing(parsed.spacing || 2);
            setDistance(getManhattanDistance(parsed.board, parsed.gridSize));
        } catch(e) {
            initBoard(gridSize);
        }
    } else {
        initBoard(gridSize);
    }
  }, []);

  // Periodic Auto-save
  useEffect(() => {
    if (board.length > 0) {
      const stateToSave = { board, moves, seconds, imageUrl, gridSize, history: historyRef.current, difficulty, spacing };
      localStorage.setItem('puzzle_current_state', JSON.stringify(stateToSave));
    }
    setDistance(getManhattanDistance(board, gridSize));
  }, [board, moves, seconds, imageUrl, gridSize, difficulty, spacing]);

  useEffect(() => {
    if (moves > 0 && !isGameFinished && !isSolving) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [moves, isGameFinished, isSolving]);

  const handleMove = (index: number, silent = false) => {
    if (isSolving && !silent) return;
    const emptyIdx = board.indexOf(board.length - 1);
    if (isAdjacent(index, emptyIdx, gridSize)) {
      historyRef.current.push([...board]);
      const newBoard = [...board];
      [newBoard[index], newBoard[emptyIdx]] = [newBoard[emptyIdx], newBoard[index]];
      setBoard(newBoard);
      setMoves(m => m + 1);
      setClueTileIdx(null);

      if (!silent && isSolved(newBoard)) {
        setIsGameFinished(true);
        saveStats(moves + 1, seconds, gridSize);
      }
    }
  };

  const saveStats = (m: number, t: number, s: GridSize) => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const entry: StatsEntry = { date: new Date().toLocaleDateString(), moves: m, time: t, gridSize: `${s.rows}x${s.cols}` };
    const updated = [entry, ...stats].slice(0, 50); // Store more so we can filter best 10
    localStorage.setItem('puzzle_stats', JSON.stringify(updated));
  };

  const shuffle = () => {
    if (isSolving) return;
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    historyRef.current = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      historyRef.current.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }
    setBoard(curr);
    setMoves(0);
    setSeconds(0);
    setIsGameFinished(false);
    setClueTileIdx(null);
  };

  const undo = () => {
    if (isSolving || historyRef.current.length === 0) return;
    const last = historyRef.current.pop();
    if (last) {
      setBoard(last);
      setMoves(m => Math.max(0, m - 1));
      setClueTileIdx(null);
    }
  };

  const getClue = () => {
    if (isSolving || isGameFinished) return;
    const emptyIdx = board.indexOf(board.length - 1);
    const movables = getMovableIndices(emptyIdx, gridSize);
    let target = movables[Math.floor(Math.random() * movables.length)];
    if (historyRef.current.length > 0) {
        const lastBoard = historyRef.current[historyRef.current.length - 1];
        const lastMovedVal = lastBoard[emptyIdx];
        const betterMoves = movables.filter(idx => board[idx] !== lastMovedVal);
        if (betterMoves.length > 0) target = betterMoves[Math.floor(Math.random() * betterMoves.length)];
    }
    setClueTileIdx(target);
  };

  const solve = async () => {
    if (isSolving) {
      abortSolvingRef.current = true;
      return;
    }
    if (isSolved(board)) return;
    setIsSolving(true);
    abortSolvingRef.current = false;

    const steps = [...historyRef.current].reverse();
    for (const step of steps) {
      if (abortSolvingRef.current) break;
      const targetEmpty = step.indexOf(board.length - 1);
      const movingTileValue = board[targetEmpty];
      const movingTileCurrentIdx = board.indexOf(movingTileValue);
      setMovingTileIdx(movingTileCurrentIdx);
      await new Promise(r => setTimeout(r, 1000));
      if (abortSolvingRef.current) break;
      setBoard(step);
      setMoves(m => m + 1);
      setMovingTileIdx(null);
      if (isSolved(step)) break;
    }
    setIsSolving(false);
    if (isSolved(board)) setIsGameFinished(true);
  };

  const saveExplicitly = () => {
    const data = { board, moves, seconds, imageUrl, gridSize, history: historyRef.current, difficulty, spacing };
    localStorage.setItem('puzzle_manual_save', JSON.stringify(data));
    alert("Game saved successfully!");
  };

  const loadExplicitly = () => {
    const data = localStorage.getItem('puzzle_manual_save');
    if (data) {
        const parsed = JSON.parse(data);
        setBoard(parsed.board);
        setMoves(parsed.moves);
        setSeconds(parsed.seconds);
        setImageUrl(parsed.imageUrl);
        setGridSize(parsed.gridSize);
        historyRef.current = parsed.history || [];
        setDifficulty(parsed.difficulty || 'Medium');
        setSpacing(parsed.spacing || 2);
        setIsMenuOpen(false);
        alert("Game loaded successfully!");
    } else {
        alert("No saved game found.");
    }
  };

  const pickImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const url = ev.target?.result as string;
        setImageUrl(url);
        const updated = [url, ...imageHistory.filter(x => x !== url)].slice(0, 10);
        setImageHistory(updated);
        localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex flex-col items-center justify-between h-full w-full py-8 px-4 bg-slate-950">
      <button 
        onClick={() => setIsMenuOpen(true)}
        className="absolute top-4 left-4 p-3 rounded-full bg-slate-800 hover:bg-slate-700 transition-colors z-40 shadow-lg"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
      </button>

      <div className="text-center">
        <h1 className="text-2xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-indigo-500 tracking-tighter mb-1">PUZZLE MASTER</h1>
        <div className="flex gap-6 text-sm font-bold text-slate-400 uppercase tracking-widest">
            <div className="flex flex-col items-center">
                <span className="text-white text-lg">{moves}</span>
                <span>Moves</span>
            </div>
            <div className="flex flex-col items-center">
                <span className="text-white text-lg">{Math.floor(seconds/60)}:{(seconds%60).toString().padStart(2,'0')}</span>
                <span>Time</span>
            </div>
            <div className="flex flex-col items-center">
                <span className="text-blue-400 text-lg">{distance}</span>
                <span>Dist.</span>
            </div>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center w-full max-h-[60vh]">
        <PuzzleBoard 
          board={board} 
          gridSize={gridSize} 
          imageUrl={imageUrl} 
          onTileClick={handleMove}
          spacing={spacing}
          movingTileIdx={movingTileIdx}
          clueTileIdx={clueTileIdx}
        />
      </div>

      <div className="w-full max-w-sm">
        <Controls 
          onShuffle={shuffle}
          onSolve={solve}
          onClue={getClue}
          onUndo={undo}
          isSolving={isSolving}
        />
      </div>

      {isGameFinished && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm animate-in fade-in duration-300">
            <div className="bg-slate-900 border border-slate-700 p-8 rounded-3xl shadow-2xl text-center max-w-xs mx-auto">
                <div className="w-16 h-16 bg-blue-500 rounded-full flex items-center justify-center mx-auto mb-4">
                    <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="M20 6 9 17l-5-5"/></svg>
                </div>
                <h2 className="text-2xl font-bold mb-2">Victory!</h2>
                <p className="text-slate-400 mb-6">You solved it in {moves} moves and {Math.floor(seconds/60)}:{(seconds%60).toString().padStart(2,'0')}. Play again?</p>
                <div className="flex flex-col gap-3">
                    <button 
                        onClick={() => { initBoard(gridSize); shuffle(); }}
                        className="w-full py-4 bg-blue-600 hover:bg-blue-500 rounded-2xl font-bold shadow-lg transition-all"
                    >
                        PLAY AGAIN
                    </button>
                    <button 
                        onClick={() => setIsGameFinished(false)}
                        className="w-full py-4 bg-slate-800 hover:bg-slate-700 rounded-2xl font-bold text-slate-300 transition-all"
                    >
                        CLOSE
                    </button>
                </div>
            </div>
        </div>
      )}

      <Menu 
        isOpen={isMenuOpen}
        onClose={() => setIsMenuOpen(false)}
        gridSize={gridSize}
        setGridSize={(s) => { setGridSize(s); initBoard(s); }}
        difficulty={difficulty}
        setDifficulty={setDifficulty}
        spacing={spacing}
        setSpacing={setSpacing}
        imageHistory={imageHistory}
        onSelectHistoryImage={setImageUrl}
        onPickImage={pickImage}
        onSave={saveExplicitly}
        onLoad={loadExplicitly}
      />
    </div>
  );
};

export default App;

import React from 'react';
import { GridSize, Difficulty, StatsEntry } from '../types';

interface MenuProps {
  isOpen: boolean;
  onClose: () => void;
  gridSize: GridSize;
  setGridSize: (s: GridSize) => void;
  difficulty: Difficulty;
  setDifficulty: (d: Difficulty) => void;
  spacing: number;
  setSpacing: (v: number) => void;
  imageHistory: string[];
  onSelectHistoryImage: (url: string) => void;
  onPickImage: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onSave: () => void;
  onLoad: () => void;
}

const Menu: React.FC<MenuProps> = ({
  isOpen, onClose, gridSize, setGridSize, difficulty, setDifficulty,
  spacing, setSpacing, imageHistory, onSelectHistoryImage, onPickImage,
  onSave, onLoad
}) => {
  if (!isOpen) return null;

  const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
  // Sort stats by moves to get "Best 10"
  const bestStats = [...stats].sort((a, b) => a.moves - b.moves).slice(0, 10);

  return (
    <div className="fixed inset-0 z-50 flex overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-72 h-full bg-slate-900 shadow-2xl p-6 flex flex-col gap-8 animate-menu border-r border-white/5 overflow-y-auto">
        <div className="flex items-center justify-between">
            <h2 className="text-xl font-black tracking-tighter">SETTINGS</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-lg">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
        </div>

        {/* Persistence Actions */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Game State</h3>
            <div className="grid grid-cols-2 gap-2">
                <button onClick={onSave} className="py-3 bg-blue-600/10 border border-blue-500/30 text-blue-400 rounded-xl text-xs font-bold hover:bg-blue-600/20 transition-all">Save Game</button>
                <button onClick={onLoad} className="py-3 bg-indigo-600/10 border border-indigo-500/30 text-indigo-400 rounded-xl text-xs font-bold hover:bg-indigo-600/20 transition-all">Load Game</button>
            </div>
        </section>

        {/* Pick Picture */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Image Selection</h3>
            <label className="flex flex-col items-center justify-center w-full h-20 border-2 border-dashed border-slate-700 rounded-2xl hover:bg-slate-800 transition-colors cursor-pointer group">
                <span className="text-xs text-slate-500 font-bold group-hover:text-blue-400">Pick from Gallery</span>
                <input type="file" accept="image/*" onChange={(e) => { onPickImage(e); onClose(); }} className="hidden" />
            </label>
        </section>

        {/* Recent Pictures History */}
        {imageHistory.length > 0 && (
            <section>
                <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Recent Gallery</h3>
                <div className="grid grid-cols-4 gap-2">
                    {imageHistory.map((url, i) => (
                        <button 
                            key={i} 
                            onClick={() => { onSelectHistoryImage(url); onClose(); }}
                            className="w-full aspect-square rounded-lg bg-cover bg-center border border-white/10 hover:border-blue-500 transition-all"
                            style={{ backgroundImage: `url(${url})` }}
                        />
                    ))}
                </div>
            </section>
        )}

        {/* Grid Selection */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Puzzle Grid</h3>
            <div className="grid grid-cols-3 gap-2">
                {[ {r:3, c:3}, {r:4, c:4}, {r:5, c:4} ].map((g, i) => (
                    <button 
                        key={i} 
                        onClick={() => { setGridSize({rows: g.r, cols: g.c}); onClose(); }}
                        className={`py-3 rounded-xl text-xs font-bold transition-all border ${
                            gridSize.rows === g.r && gridSize.cols === g.c 
                            ? 'bg-blue-600 border-blue-400' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {g.r}x{g.c}
                    </button>
                ))}
            </div>
        </section>

        {/* Difficulty Setting */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Shuffling (Difficulty)</h3>
            <div className="flex gap-2">
                {(['Easy', 'Medium', 'Hard'] as Difficulty[]).map(d => (
                    <button 
                        key={d} 
                        onClick={() => setDifficulty(d)}
                        className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all border ${
                            difficulty === d 
                            ? 'bg-indigo-600 border-indigo-400' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {d}
                    </button>
                ))}
            </div>
        </section>

        {/* Spacing Adjustment */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Tile Spacing</h3>
            <div className="flex items-center gap-4">
                <input 
                    type="range" min="0" max="10" 
                    value={spacing} onChange={(e) => setSpacing(parseInt(e.target.value))}
                    className="flex-1 h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
                />
                <span className="text-xs font-mono text-slate-500">{spacing}px</span>
            </div>
        </section>

        {/* Best 10 Stats Display */}
        <section className="mt-auto border-t border-white/5 pt-6 pb-6">
            <h3 className="text-[10px] font-bold text-blue-400 uppercase tracking-[0.2em] mb-3">Best 10 Games</h3>
            <div className="space-y-2 max-h-48 overflow-y-auto">
                {bestStats.length === 0 ? (
                    <p className="text-[10px] text-slate-600 italic">Complete a game to see stats.</p>
                ) : (
                    bestStats.map((s, i) => (
                        <div key={i} className="flex justify-between items-center bg-slate-800/40 p-2 rounded-lg text-[10px]">
                            <div className="flex flex-col">
                                <span className="font-bold text-slate-300">{s.gridSize}</span>
                                <span className="text-[8px] text-slate-600">{s.date}</span>
                            </div>
                            <div className="text-right">
                                <span className="text-blue-400 font-bold">{s.moves} moves</span>
                                <span className="block text-[8px] text-slate-600">{s.time}s</span>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </section>
      </div>
    </div>
  );
};

export default Menu;

