        <div className="flex items-center justify-between">
            <h2 className="text-xl font-black tracking-tighter">SETTINGS</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-lg">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
        </div>

        {/* AI Image Gen */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">AI Image Generation</h3>
            <div className="flex gap-2">
                <input 
                    type="text" 
                    placeholder="Describe a picture..."
                    value={prompt}
                    onChange={(e) => setPrompt(e.target.value)}
                    className="flex-1 bg-slate-800 border border-slate-700 rounded-xl px-4 py-2 text-xs focus:border-blue-500 outline-none"
                />
                <button 
                    onClick={() => onGenerateAI(prompt)}
