        {/* Grid Selection */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Select Grid</h3>
            <div className="grid grid-cols-3 gap-2">
                {[ {r:3, c:3}, {r:4, c:4}, {r:5, c:4} ].map((g, i) => (
                    <button 
                        key={i} 
                        onClick={() => { setGridSize({rows: g.r, cols: g.c}); onClose(); }}
                        className={`py-3 rounded-xl text-xs font-bold transition-all border ${
                            gridSize.rows === g.r && gridSize.cols === g.c 
                            ? 'bg-blue-600 border-blue-400 text-white shadow-lg' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {g.r}x{g.c}
                    </button>
                ))}
            </div>
        </section>

        {/* Difficulty Setting */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Difficulty</h3>
            <div className="flex gap-2">
                {(['Easy', 'Medium', 'Hard'] as Difficulty[]).map(d => (
                    <button 
                        key={d} 
                        onClick={() => setDifficulty(d)}
                        className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all border ${
                            difficulty === d 
                            ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {d}
                    </button>
                ))}
            </div>
        </section>

        {/* Spacing Setting */}
        <section>
            <div className="flex justify-between items-center mb-2">
                <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">Tile Spacing</h3>
                <span className="text-xs font-bold text-blue-400">{spacing}px</span>
            </div>
            <input 
                type="range" min="0" max="10" value={spacing} 
                onChange={(e) => setSpacing(parseInt(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
            />
        </section>

        {/* Stats Display */}
        <section className="mt-auto border-t border-white/5 pt-6 pb-4">
            <h3 className="text-[10px] font-bold text-blue-400 uppercase tracking-[0.2em] mb-4">Hall of Fame (Best 10)</h3>
            <div className="space-y-2 max-h-40 overflow-y-auto pr-1">
                {bestStats.length === 0 ? (
                    <p className="text-[10px] text-slate-600 italic text-center py-4">No records yet. Win a game to show up here!</p>
                ) : (
                    bestStats.map((s, i) => (
                        <div key={i} className="flex justify-between items-center bg-slate-800/40 p-3 rounded-xl text-[10px] border border-white/5">
                            <div className="flex flex-col">
                                <span className="font-bold text-slate-300 uppercase">{s.gridSize} Grid</span>
                                <span className="text-slate-600">{s.date}</span>
                            </div>
                            <div className="text-right">
                                <div className="text-blue-400 font-black">{s.moves} moves</div>
                                <div className="text-slate-500">{s.time}s</div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </section>
      </div>
    </div>
  );
};

export default Menu;

{
  "name": "lumina-puzzle-master",
  "version": "1.1.0",
  "type": "module",
  "description": "Sliding puzzle game with custom image support and state persistence",
  "scripts": {
    "dev": "vite",
    "build": "vite build",
    "preview": "vite preview"
  },
  "dependencies": {
    "react": "19.0.0",
    "react-dom": "19.0.0",
    "vite": "^6.0.3"
  },
  "devDependencies": {
    "@types/react": "19.0.0",
    "@types/react-dom": "19.0.0",
    "@vitejs/plugin-react": "^4.3.4",
    "typescript": "5.7.2"
  }
}

{
  "rewrites": [
    { "source": "/(.*)", "destination": "/index.html" }
  ]
}

const CACHE_NAME = 'lumina-puzzle-v1';
const ASSETS = [
  '/',
  '/index.html',
  'https://cdn.tailwindcss.com',
  'https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&display=swap'
];

self.addEventListener('install', (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then((cache) => cache.addAll(ASSETS))
  );
});

self.addEventListener('fetch', (event) => {
  event.respondWith(
    caches.match(event.request).then((response) => {
      return response || fetch(event.request);
    })
  );
});

export type GridSize = {
  rows: number;
  cols: number;
};

export type Difficulty = 'Easy' | 'Medium' | 'Hard';

export interface GameState {
  board: number[];
  moves: number;
  seconds: number;
  imageUrl: string;
  gridSize: GridSize;
  history: number[][];
  difficulty: Difficulty;
  spacing: number;
  showNumbers: boolean;
}

export interface StatsEntry {
  date: string;
  moves: number;
  time: number;
  gridSize: string;
}

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry } from './types';
import { isAdjacent, getMovableIndices, isSolved, getManhattanDistance } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/800/800?random=42';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [distance, setDistance] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);

  const historyRef = useRef<number[][]>([]);
  const timerRef = useRef<number | null>(null);
  const abortSolvingRef = useRef(false);

  const updateBestMoves = useCallback(() => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const relevant = stats.filter(s => s.gridSize === `${gridSize.rows}x${gridSize.cols}`);
    if (relevant.length > 0) {
      const min = Math.min(...relevant.map(r => r.moves));
      setBestMoves(min);
    } else {
      setBestMoves(null);
    }
  }, [gridSize]);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setDistance(0);
    historyRef.current = [];
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves();
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastState = localStorage.getItem('puzzle_current_state');
    if (lastState) {
        try {
            const parsed = JSON.parse(lastState);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setSeconds(parsed.seconds);
            setImageUrl(parsed.imageUrl);
            setGridSize(parsed.gridSize);
            historyRef.current = parsed.history || [];
            setDifficulty(parsed.difficulty || 'Medium');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setDistance(getManhattanDistance(parsed.board, parsed.gridSize));
            setIsGameFinished(isSolved(parsed.board) && parsed.moves > 0);
        } catch(e) {
            initBoard(gridSize);
        }
    } else {
        initBoard(gridSize);
    }
    updateBestMoves();
  }, [gridSize, initBoard, updateBestMoves]);

  useEffect(() => {
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) setImageHistory(JSON.parse(storedHistory));
    loadSavedState();
  }, []);

  useEffect(() => {
    if (board.length > 0) {
      const stateToSave = { board, moves, seconds, imageUrl, gridSize, history: historyRef.current, difficulty, spacing, showNumbers };
      localStorage.setItem('puzzle_current_state', JSON.stringify(stateToSave));
    }
    setDistance(getManhattanDistance(board, gridSize));
  }, [board, moves, seconds, imageUrl, gridSize, difficulty, spacing, showNumbers]);

  useEffect(() => {
    if (moves > 0 && !isGameFinished && !isSolving) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [moves, isGameFinished, isSolving]);

  const handleMove = (index: number, silent = false) => {
    if (isSolving && !silent) return;
    const emptyIdx = board.indexOf(board.length - 1);
    if (isAdjacent(index, emptyIdx, gridSize)) {
      historyRef.current.push([...board]);
      const newBoard = [...board];
      [newBoard[index], newBoard[emptyIdx]] = [newBoard[emptyIdx], newBoard[index]];
      setBoard(newBoard);
      if (!silent) setMoves(m => m + 1);
      setClueTileIdx(null);

      if (!silent && isSolved(newBoard)) {
        setIsGameFinished(true);
        saveStats(moves + 1, seconds, gridSize);
      }
    }
  };

  const saveStats = (m: number, t: number, s: GridSize) => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const entry: StatsEntry = { date: new Date().toLocaleDateString(), moves: m, time: t, gridSize: `${s.rows}x${s.cols}` };
    const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
    localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    updateBestMoves();
  };

  const shuffle = () => {
    if (isSolving) return;
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    historyRef.current = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      historyRef.current.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }
    setBoard(curr);
    setMoves(0);
    setSeconds(0);
    setIsGameFinished(false);
    setClueTileIdx(null);
  };

  const undo = () => {
    if (isSolving || historyRef.current.length === 0) return;
    const last = historyRef.current.pop();
    if (last) {
      setBoard(last);
      setMoves(m => Math.max(0, m - 1));
      setClueTileIdx(null);
    }
  };

  const getClue = () => {
    if (isSolving || isGameFinished) return;
    const emptyIdx = board.indexOf(board.length - 1);
    const movables = getMovableIndices(emptyIdx, gridSize);
    // Find a tile that isn't already in its correct position if possible
    const misplaced = movables.filter(idx => board[idx] !== idx);
    const target = misplaced.length > 0 
      ? misplaced[Math.floor(Math.random() * misplaced.length)]
      : movables[Math.floor(Math.random() * movables.length)];
    setClueTileIdx(target);
  };

  const solve = async () => {
    if (isSolving) {
      abortSolvingRef.current = true;
      return;
    }
    if (isSolved(board)) return;
    setIsSolving(true);
    abortSolvingRef.current = false;

    const steps = [...historyRef.current].reverse();
    for (const step of steps) {
      if (abortSolvingRef.current) break;
      const targetEmptyIdx = step.indexOf(board.length - 1);
      const tileToMoveValue = board[targetEmptyIdx];
      const currentTileIdx = board.indexOf(tileToMoveValue);

      setMovingTileIdx(currentTileIdx);
      await new Promise(r => setTimeout(r, 1000));

      if (abortSolvingRef.current) break;
      setBoard(step);
      setMoves(m => m + 1);
      setMovingTileIdx(null);
      if (isSolved(step)) break;
    }
    setIsSolving(false);
    if (isSolved(board)) setIsGameFinished(true);
  };

  const pickImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const url = ev.target?.result as string;
        setImageUrl(url);
        const updated = [url, ...imageHistory.filter(x => x !== url)].slice(0, 10);
        setImageHistory(updated);
        localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
      };
      reader.readAsDataURL(file);
    }
  };

  return (
    <div className="flex flex-col items-center justify-between h-full w-full py-2 px-4 bg-slate-950 overflow-hidden relative">
      <button 
        onClick={() => setIsMenuOpen(true)}
        className="absolute top-4 left-4 p-3 rounded-full bg-slate-800 hover:bg-slate-700 transition-colors z-40 shadow-lg"
      >
        <svg xmlns="http://www.w3.org/2000/svg" width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
      </button>

      <div className="text-center mt-2 flex flex-col items-center">
        <h1 className="text-xl font-black text-transparent bg-clip-text bg-gradient-to-r from-blue-400 to-indigo-500 tracking-tighter mb-1 uppercase">Puzzle Master</h1>
        <div className="flex gap-4 text-[10px] font-bold text-slate-400 uppercase tracking-widest justify-center">
            <div className="flex flex-col items-center">
                <span className="text-white text-base leading-none mb-1">{moves}</span>
                <span>Moves</span>
            </div>
            <div className="flex flex-col items-center">
                <span className="text-blue-400 text-base leading-none mb-1">{bestMoves ?? '--'}</span>
                <span>Best</span>
            </div>
            <div className="flex flex-col items-center">
                <span className="text-white text-base leading-none mb-1">{distance}</span>
                <span>Distance</span>
            </div>
            <div className="flex flex-col items-center">
                <span className="text-white text-base leading-none mb-1">{Math.floor(seconds/60)}:{(seconds%60).toString().padStart(2,'0')}</span>
                <span>Time</span>
            </div>
        </div>
      </div>

      <div className="flex-1 flex items-center justify-center w-full min-h-0 py-2">
        <PuzzleBoard 
          board={board} 
          gridSize={gridSize} 
          imageUrl={imageUrl} 
          onTileClick={handleMove}
          spacing={spacing}
          movingTileIdx={movingTileIdx}
          clueTileIdx={clueTileIdx}
          showNumbers={showNumbers}
        />
      </div>

      <div className="w-full max-w-sm mb-4">
        <Controls 
          onShuffle={shuffle}
          onSolve={solve}
          onClue={getClue}
          onUndo={undo}
          isSolving={isSolving}
        />
      </div>

      {isGameFinished && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/80 backdrop-blur-sm p-6">
            <div className="bg-slate-900 border border-slate-700 p-8 rounded-3xl shadow-2xl text-center w-full max-w-xs animate-menu">
