  difficulty: Difficulty;
  setDifficulty: (d: Difficulty) => void;
  spacing: number;
  setSpacing: (v: number) => void;
  showNumbers: boolean;
  setShowNumbers: (v: boolean) => void;
  tileShape: TileShape;
  setTileShape: (s: TileShape) => void;
  imageHistory: string[];
  onSelectHistoryImage: (url: string) => void;
  onPickImage: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onLoadSaved: () => void;
}

const Menu: React.FC<MenuProps> = ({
  isOpen, onClose, gridSize, setGridSize, difficulty, setDifficulty,
  spacing, setSpacing, showNumbers, setShowNumbers, tileShape, setTileShape,
  imageHistory, onSelectHistoryImage, onPickImage, onLoadSaved
}) => {
  if (!isOpen) return null;

  const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
  const bestStats = [...stats].sort((a, b) => a.moves - b.moves).slice(0, 10);

  return (
    <div className="fixed inset-0 z-50 flex overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={onClose} />
      <div className="relative w-80 h-full bg-slate-900 shadow-2xl p-6 flex flex-col gap-6 animate-menu border-r border-white/5 overflow-y-auto">
        <div className="flex items-center justify-between">
            <h2 className="text-xl font-black tracking-tighter text-white">GAME MENU</h2>
            <button onClick={onClose} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
            </button>
        </div>

        {/* Persistence */}
        <section>
            <button 
                onClick={() => { onLoadSaved(); onClose(); }}
                className="w-full py-4 bg-blue-600/20 border border-blue-500/30 text-blue-400 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-600/30 transition-all active:scale-95"
            >
                LOAD SAVED STATE
            </button>
        </section>

        {/* Pick Picture */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">PICK PICTURE</h3>
            <label className="flex flex-col items-center justify-center w-full h-20 bg-slate-800 border-2 border-slate-700 border-dashed rounded-2xl hover:bg-slate-750 transition-all cursor-pointer group mb-4 active:scale-95">
                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className="mb-2 text-slate-500 group-hover:text-blue-400"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                <span className="text-xs text-slate-400 font-black group-hover:text-blue-400 tracking-tighter uppercase">Gallery Upload</span>
                <input type="file" accept="image/*" onChange={(e) => { onPickImage(e); onClose(); }} className="hidden" />
            </label>
            {imageHistory.length > 0 && (
                <div className="flex gap-2 overflow-x-auto pb-2 scrollbar-hide">
                    {imageHistory.map((url, i) => (
                        <button 
                            key={i} 
                            onClick={() => { onSelectHistoryImage(url); onClose(); }}
                            className="flex-shrink-0 w-12 h-12 rounded-lg bg-cover bg-center border-2 border-slate-700 active:scale-90 transition-all hover:border-blue-500"
                            style={{ backgroundImage: `url(${url})` }}
                        />
                    ))}
                </div>
            )}
        </section>

        {/* Toggles */}
        <section className="flex items-center justify-between p-4 bg-slate-800/50 rounded-2xl border border-white/5">
            <span className="text-xs font-black text-slate-300 tracking-tight uppercase">SHOW NUMBERS</span>
            <button 
                onClick={() => setShowNumbers(!showNumbers)}
                className={`relative w-12 h-6 rounded-full transition-colors ${showNumbers ? 'bg-blue-600' : 'bg-slate-700'}`}
            >
                <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showNumbers ? 'left-7' : 'left-1'}`} />
            </button>
        </section>

        {/* Tile Shape Selection */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">TILE SHAPE</h3>
            <div className="flex gap-2">
                {(['square', 'rounded'] as TileShape[]).map(s => (
                    <button 
                        key={s} 
                        onClick={() => setTileShape(s)}
                        className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all border uppercase tracking-widest ${
                            tileShape === s 
                            ? 'bg-blue-600 border-blue-400 text-white shadow-lg' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {s.toUpperCase()}
                    </button>
                ))}
            </div>
        </section>

        {/* Grid Selection */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">SELECT GRID</h3>
            <div className="grid grid-cols-3 gap-2">
                {[ {r:3, c:3}, {r:4, c:4}, {r:5, c:4} ].map((g, i) => (
                    <button 
                        key={i} 
                        onClick={() => { setGridSize({rows: g.r, cols: g.c}); onClose(); }}
                        className={`py-3 rounded-xl text-xs font-bold transition-all border ${
                            gridSize.rows === g.r && gridSize.cols === g.c 
                            ? 'bg-blue-600 border-blue-400 text-white shadow-lg' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {g.r}x{g.c}
                    </button>
                ))}
            </div>
        </section>

        {/* Difficulty Setting */}
        <section>
            <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">DIFFICULTY</h3>
            <div className="flex gap-2">
                {(['Easy', 'Medium', 'Hard'] as Difficulty[]).map(d => (
                    <button 
                        key={d} 
                        onClick={() => setDifficulty(d)}
                        className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all border uppercase tracking-widest ${
                            difficulty === d 
                            ? 'bg-indigo-600 border-indigo-400 text-white shadow-lg' 
                            : 'bg-slate-800 border-white/5 text-slate-400'
                        }`}
                    >
                        {d}
                    </button>
                ))}
            </div>
        </section>

        {/* Spacing Setting */}
        <section>
            <div className="flex justify-between items-center mb-2">
                <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em]">TILE SPACING</h3>
                <span className="text-xs font-bold text-blue-400">{spacing}px</span>
            </div>
            <input 
                type="range" min="0" max="10" value={spacing} 
                onChange={(e) => setSpacing(parseInt(e.target.value))}
                className="w-full h-1.5 bg-slate-800 rounded-lg appearance-none cursor-pointer accent-blue-500"
            />
        </section>

        {/* Stats Display */}
        <section className="mt-auto border-t border-white/5 pt-6 pb-4">
            <h3 className="text-[10px] font-bold text-blue-400 uppercase tracking-[0.2em] mb-4">HALL OF FAME</h3>
            <div className="space-y-2 max-h-40 overflow-y-auto pr-1">
                {bestStats.length === 0 ? (
                    <p className="text-[10px] text-slate-600 italic text-center py-4">No records yet. Win a game to show up here!</p>
                ) : (
                    bestStats.map((s, i) => (
                        <div key={i} className="flex justify-between items-center bg-slate-800/40 p-3 rounded-xl text-[10px] border border-white/5">
                            <div className="flex flex-col">
                                <span className="font-bold text-slate-300 uppercase">{s.gridSize} GRID</span>
                                <span className="text-slate-600 uppercase">{s.date}</span>
                            </div>
                            <div className="text-right">
                                <div className="text-blue-400 font-black uppercase">{s.moves} MOVES</div>
                                <div className="text-slate-500 uppercase">{s.time}S</div>
                            </div>
                        </div>
                    ))
                )}
            </div>
        </section>
      </div>
    </div>
  );
};

export default Menu;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved, getManhattanDistance } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/800/800?random=42';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [distance, setDistance] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Medium');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);

  const historyRef = useRef<number[][]>([]);
  const timerRef = useRef<number | null>(null);
  const abortSolvingRef = useRef(false);

  const updateBestMoves = useCallback(() => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${gridSize.rows}x${gridSize.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) {
      setBestMoves(null);
    }
  }, [gridSize]);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setDistance(0);
    setHasShuffled(false);
    historyRef.current = [];
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves();
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastState = localStorage.getItem('puzzle_current_state');
    if (lastState) {
        try {
            const parsed = JSON.parse(lastState);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(parsed.seconds);
            setImageUrl(parsed.imageUrl);
            setGridSize(parsed.gridSize);
            historyRef.current = parsed.history || [];
            setDifficulty(parsed.difficulty || 'Medium');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            setDistance(getManhattanDistance(parsed.board, parsed.gridSize));
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) {
            initBoard(gridSize);
        }
    } else {
        initBoard(gridSize);
    }
    updateBestMoves();
  }, [gridSize, initBoard, updateBestMoves]);

  useEffect(() => {
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) {
      try {
        setImageHistory(JSON.parse(storedHistory));
      } catch (e) {
        setImageHistory([]);
      }
    }
    loadSavedState();
  }, []);

  useEffect(() => {
    if (board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, seconds, imageUrl, gridSize, 
        history: historyRef.current, difficulty, spacing, 
        showNumbers, tileShape, hasShuffled 
      };
      try {
        localStorage.setItem('puzzle_current_state', JSON.stringify(stateToSave));
      } catch (e) {
        localStorage.removeItem('puzzle_image_history');
      }
    }
    setDistance(getManhattanDistance(board, gridSize));
  }, [board, moves, requiredMoves, seconds, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else {
      if (timerRef.current) {
        clearInterval(timerRef.current);
        timerRef.current = null;
      }
    }
    return () => {};
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
    const entry: StatsEntry = { 
      date: new Date().toLocaleDateString(), 
      moves: m, 
      time: t, 
      gridSize: `${s.rows}x${s.cols}` 
    };
    const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
    localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    updateBestMoves();
  }, [updateBestMoves]);

  const handleMove = (index: number, silent = false) => {
    if (isSolving && !silent) return;
    const emptyIdx = board.indexOf(board.length - 1);

    if (isAdjacent(index, emptyIdx, gridSize)) {
      const currentBoard = [...board];
      const nextBoard = [...board];
      [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

      const previousState = historyRef.current[historyRef.current.length - 1];
      const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);

      if (isCorrectBacktrack) {
        historyRef.current.pop();
      } else {
        historyRef.current.push(currentBoard);
      }

      setBoard(nextBoard);

      if (!silent) {
        const nextMoves = moves + 1;
        setMoves(nextMoves);
        setClueTileIdx(null);
        if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
          setIsGameFinished(true);
          saveStats(nextMoves, seconds, gridSize);
        }
      }
    }
  };

  const shuffle = () => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    historyRef.current = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      historyRef.current.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(shuffleCount);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  };

  const undo = () => {
    if (isSolving || historyRef.current.length === 0) return;
    const last = historyRef.current.pop();
    if (last) {
      setBoard(last);
      setMoves(m => m + 1);
      setClueTileIdx(null);
      setIsGameFinished(false);
    }
  };

  const getClue = () => {
    if (isSolving || isGameFinished || !hasShuffled || historyRef.current.length === 0) return;
    const previousState = historyRef.current[historyRef.current.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  };

  const solve = async () => {
    if (isSolving) {
      abortSolvingRef.current = true;
      return;
    }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let moveCounter = moves;
    while (historyRef.current.length > 0 && !abortSolvingRef.current) {
      const previousState = historyRef.current[historyRef.current.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);

      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));

      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      historyRef.current.pop();
      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, seconds, gridSize);
          break;
      }
    }
    setIsSolving(false);
  };

  const pickImage = (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const MAX_SIZE = 700;
            let width = img.width;
            let height = img.height;
            if (width > height) {
                if (width > MAX_SIZE) {
                    height *= MAX_SIZE / width;
                    width = MAX_SIZE;
                }
            } else {
                if (height > MAX_SIZE) {
                    width *= MAX_SIZE / height;
                    height = MAX_SIZE;
                }
            }
            canvas.width = width;
            canvas.height = height;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, 0, 0, width, height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.6);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) {
                localStorage.removeItem('puzzle_image_history');
              }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  };

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-8">

      {/* HEADER SECTION */}
      <div className="w-full max-w-[420px] mb-6 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-6">
            <button 
                onClick={() => setIsMenuOpen(true)}
                className="p-3 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-white/50 hover:text-white transition-all shadow-lg active:scale-90"
            >
                <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
            </button>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2">
                <span className="opacity-40">LUMINA</span> 
                <span className="text-blue-500 drop-shadow-[0_0_8px_rgba(59,130,246,0.3)]">PUZZLE</span>
            </h1>
            <div className="w-[44px]"></div> {/* Spacer for symmetry */}
        </div>

        {/* HUD DASHBOARD */}
        <div className="grid grid-cols-5 w-full gap-2">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Dist', val: distance, color: 'text-white/50' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2 px-1 rounded-xl">
                    <span className={`text-xs font-black leading-none mb-1 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-extrabold text-slate-500 tracking-[0.1em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>

      {/* BOARD SECTION: No more "well" or "tray" constraints */}
      <div className="flex items-center justify-center mb-8">
          <PuzzleBoard 
            board={board} 
            gridSize={gridSize} 
            imageUrl={imageUrl} 
            onTileClick={handleMove}
            spacing={spacing}
            movingTileIdx={movingTileIdx}
            clueTileIdx={clueTileIdx}
            showNumbers={showNumbers}
            tileShape={tileShape}
          />
      </div>

      {/* CONTROLS SECTION */}
      <div className="w-full max-w-[420px] pb-8">
          <Controls 
            onShuffle={shuffle}
            onSolve={solve}
            onClue={getClue}
            onUndo={undo}
            isSolving={isSolving}
          />
      </div>

      {/* Win Modal Overlay */}
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/90 backdrop-blur-md p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-6 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-8 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={() => shuffle()} className="w-full py-4 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-4 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                </div>
            </div>
        </div>
      )}

      {/* Menu Sidebar */}
      <Menu 
        isOpen={isMenuOpen}
        onClose={() => setIsMenuOpen(false)}
        gridSize={gridSize}
        setGridSize={(s) => { setGridSize(s); initBoard(s); }}
        difficulty={difficulty}
        setDifficulty={setDifficulty}
        spacing={spacing}
        setSpacing={setSpacing}
        showNumbers={showNumbers}
        setShowNumbers={setShowNumbers}
        tileShape={tileShape}
        setTileShape={setTileShape}
        imageHistory={imageHistory}
        onSelectHistoryImage={setImageUrl}
        onPickImage={pickImage}
        onLoadSaved={loadSavedState}
      />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GridSize, TileShape } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  movingTileIdx: number | null;
  clueTileIdx: number | null;
  showNumbers: boolean;
  tileShape: TileShape;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = ({ 
  board, gridSize, imageUrl, onTileClick, spacing, movingTileIdx, clueTileIdx, showNumbers, tileShape 
}) => {
  const [boardSize, setBoardSize] = useState(300);

  useEffect(() => {
    const resize = () => {
      // Use window.innerWidth - 32 to ensure a 16px gutter on mobile
      const size = Math.min(window.innerWidth - 32, window.innerHeight - 320, 420);
      setBoardSize(size);
    };
    resize();
    window.addEventListener('resize', resize);
    return () => window.removeEventListener('resize', resize);
  }, []);

  const tileW = (boardSize - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileH = (boardSize - (gridSize.rows - 1) * spacing) / gridSize.rows;

  // Determine border radius based on tileShape
  const borderRadius = tileShape === 'rounded' ? '12%' : '0px';

  return (
    <div 
      className="relative"
      style={{ width: boardSize, height: boardSize }}
    >
      {board.map((val, idx) => {
        if (val === board.length - 1) return null;

        const row = Math.floor(idx / gridSize.cols);
        const col = idx % gridSize.cols;
        const origRow = Math.floor(val / gridSize.cols);
        const origCol = val % gridSize.cols;

        const left = col * (tileW + spacing);
        const top = row * (tileH + spacing);

        const isMoving = movingTileIdx === idx;
        const isClue = clueTileIdx === idx;

        return (
          <div
            key={val}
            onClick={() => onTileClick(idx)}
            className="absolute puzzle-tile-transition cursor-pointer overflow-hidden border border-white/10 shadow-lg group active:brightness-125"
            style={{
              width: tileW,
              height: tileH,
              transform: `translate(${left}px, ${top}px)`,
              borderRadius: borderRadius,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${(origCol / (gridSize.cols - 1)) * 100}% ${(origRow / (gridSize.rows - 1)) * 100}%`,
            }}
          >
            {/* Number Overlay */}
            {showNumbers && (
              <div className="absolute top-1 left-1 bg-black/60 backdrop-blur-md rounded-md px-1.5 py-0.5 min-w-[1rem] text-center border border-white/5 pointer-events-none">
                <span className="text-[9px] font-black text-white/80">{val + 1}</span>
              </div>
            )}

            {/* Clue indicator */}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none bg-amber-400/25">
                <div className="w-3 h-3 rounded-full bg-amber-400 shadow-[0_0_15px_rgba(251,191,36,1)] border-2 border-white clue-dot" />
              </div>
            )}

            {/* Moving indicator */}
            {isMoving && (
              <div className="absolute inset-0 flex items-center justify-center bg-blue-400/30 border-2 border-blue-400 pointer-events-none">
                <div className="w-full h-full border-2 border-blue-400 animate-ping opacity-50" />
              </div>
            )}

            {/* Hover/Active overlay */}
            <div className="absolute inset-0 bg-white/0 group-hover:bg-white/5 transition-colors pointer-events-none" />
          </div>
        );
      })}
    </div>
  );
};

