  const [history, setHistory] = useState<number[][]>([]);
  const [shuffleDepth, setShuffleDepth] = useState(0);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);

  // Sync ref with state for logic use without re-triggering effects
  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  const updateBestMoves = useCallback(() => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${gridSize.rows}x${gridSize.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, [gridSize]);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setDistance(0);
    setHasShuffled(false);
    setHistory([]);
    setShuffleDepth(0);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves();
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setShuffleDepth(parsed.shuffleDepth || 0);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            setDistance(getManhattanDistance(parsed.board, parsed.gridSize));
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard(gridSize); }
    } else { initBoard(gridSize); }
    updateBestMoves();
  }, [gridSize, initBoard, updateBestMoves]);

  useEffect(() => {
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) {
      try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
    }
    loadSavedState();
  }, [loadSavedState]);

  useEffect(() => {
    if (board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, shuffleDepth, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
    setDistance(getManhattanDistance(board, gridSize));
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, shuffleDepth]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  useEffect(() => {
    if (hasShuffled) setRequiredMoves(history.length);
  }, [history.length, hasShuffled]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves();
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;
    setBoard(prevBoard => {
      const emptyIdx = prevBoard.indexOf(prevBoard.length - 1);
      if (isAdjacent(index, emptyIdx, gridSize)) {
        const nextBoard = [...prevBoard];
        [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

        setHistory(prevHistory => {
          const previousState = prevHistory[prevHistory.length - 1];
          const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
          return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, prevBoard];
        });

        if (!silent) {
          setMoves(m => {
            const nextMoves = m + 1;
            if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
              setIsGameFinished(true);
              saveStats(nextMoves, secondsRef.current, gridSize);
            }
            return nextMoves;
          });
          setClueTileIdx(null);
        }
        return nextBoard;
      }
      return prevBoard;
    });
  }, [gridSize, isSolving, hasShuffled, saveStats]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setShuffleDepth(newHistory.length);
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || history.length === 0) return;
    setHistory(prev => {
      const newHistory = [...prev];
      const last = newHistory.pop();
      if (last) {
        setBoard(last);
        setMoves(m => Math.max(0, m - 1));
        setClueTileIdx(null);
        setIsGameFinished(false);
      }
      return newHistory;
    });
  }, [isSolving, history.length]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-5 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Dist', val: distance, color: 'text-white/40' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && history.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GridSize, TileShape } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  movingTileIdx: number | null;
  clueTileIdx: number | null;
  showNumbers: boolean;
  tileShape: TileShape;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = React.memo(({ 
  board, gridSize, imageUrl, onTileClick, spacing, movingTileIdx, clueTileIdx, showNumbers, tileShape 
}) => {
  const [dimensions, setDimensions] = useState({ width: 300, height: 300 });

  useEffect(() => {
    const handleResize = () => {
      const maxW = window.innerWidth - 32;
      const maxH = window.innerHeight - 360;
      const targetWidthLimit = Math.min(maxW, 420);
      const tileS = Math.floor((targetWidthLimit - (gridSize.cols - 1) * spacing) / gridSize.cols);
      let calculatedHeight = tileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      let calculatedWidth = tileS * gridSize.cols + (gridSize.cols - 1) * spacing;

      if (calculatedHeight > maxH) {
          const scaledTileS = Math.floor((maxH - (gridSize.rows - 1) * spacing) / gridSize.rows);
          calculatedWidth = scaledTileS * gridSize.cols + (gridSize.cols - 1) * spacing;
          calculatedHeight = scaledTileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      }
      setDimensions({ width: calculatedWidth, height: calculatedHeight });
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [gridSize.cols, gridSize.rows, spacing]);

  const { width: boardWidth, height: boardHeight } = dimensions;
  const tileW = (boardWidth - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileH = (boardHeight - (gridSize.rows - 1) * spacing) / gridSize.rows;
  const borderRadius = tileShape === 'rounded' ? '12px' : '0px';

  return (
    <div 
      className="relative select-none"
      style={{ 
        width: boardWidth, 
        height: boardHeight,
        perspective: '1200px',
        transformStyle: 'preserve-3d',
        touchAction: 'none'
      }}
    >
      {board.map((val, idx) => {
        if (val === board.length - 1) return null;

        const row = Math.floor(idx / gridSize.cols);
        const col = idx % gridSize.cols;
        const origRow = Math.floor(val / gridSize.cols);
        const origCol = val % gridSize.cols;
        const left = col * (tileW + spacing);
        const top = row * (tileH + spacing);

        const isMoving = movingTileIdx === idx;
        const isClue = clueTileIdx === idx;
        const bgX = gridSize.cols > 1 ? (origCol / (gridSize.cols - 1)) * 100 : 0;
        const bgY = gridSize.rows > 1 ? (origRow / (gridSize.rows - 1)) * 100 : 0;

        return (
          <div
            key={val}
            onClick={() => onTileClick(idx)}
            className="absolute puzzle-tile-transition cursor-pointer overflow-hidden border border-white/10 shadow-lg group active:brightness-125 touch-manipulation"
            style={{
              width: tileW,
              height: tileH,
              transform: `translate3d(${left}px, ${top}px, 0) translateZ(0)`,
              borderRadius: borderRadius,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${bgX}% ${bgY}%`,
              backfaceVisibility: 'hidden',
              WebkitBackfaceVisibility: 'hidden',
              willChange: 'transform'
            }}
          >
            {showNumbers && (
              <div className="absolute top-1.5 left-1.5 bg-black/60 backdrop-blur-md rounded-md px-1.5 py-0.5 min-w-[1.2rem] text-center border border-white/10 pointer-events-none">
                <span className="text-[10px] font-black text-white/90">{val + 1}</span>
              </div>
            )}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none bg-amber-400/20">
                <div className="w-5 h-5 rounded-full bg-amber-400 shadow-[0_0_20px_rgba(251,191,36,1)] border-2 border-white clue-dot" />
              </div>
            )}
            {isMoving && (
              <div className="absolute inset-0 flex items-center justify-center bg-blue-400/30 border-2 border-blue-400 pointer-events-none">
                <div className="w-full h-full border-2 border-blue-400 animate-ping opacity-50" />
              </div>
            )}
            <div className="absolute inset-0 bg-white/0 group-hover:bg-white/5 active:bg-white/10 transition-colors pointer-events-none" />
          </div>
        );
      })}
    </div>
  );
});

export default PuzzleBoard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved, getManhattanDistance } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'data:image/jpeg;base64,';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [shuffleDepth, setShuffleDepth] = useState(0);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);

  // Sync ref with state for logic use without re-triggering effects
  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  const updateBestMoves = useCallback(() => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${gridSize.rows}x${gridSize.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, [gridSize]);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setShuffleDepth(0);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves();
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setShuffleDepth(parsed.shuffleDepth || 0);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard(gridSize); }
    } else { initBoard(gridSize); }
    updateBestMoves();
  }, [gridSize, initBoard, updateBestMoves]);

  useEffect(() => {
    const storedHistory = localStorage.getItem('puzzle_image_history');
    if (storedHistory) {
      try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
    }
    loadSavedState();
  }, [loadSavedState]);

  useEffect(() => {
    if (board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, shuffleDepth, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, shuffleDepth]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  useEffect(() => {
    if (hasShuffled) setRequiredMoves(history.length);
  }, [history.length, hasShuffled]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves();
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;
    setBoard(prevBoard => {
      const emptyIdx = prevBoard.indexOf(prevBoard.length - 1);
      if (isAdjacent(index, emptyIdx, gridSize)) {
        const nextBoard = [...prevBoard];
        [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

        setHistory(prevHistory => {
          const previousState = prevHistory[prevHistory.length - 1];
          const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
          return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, prevBoard];
        });

        if (!silent) {
          setMoves(m => {
            const nextMoves = m + 1;
            if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
              setIsGameFinished(true);
              saveStats(nextMoves, secondsRef.current, gridSize);
            }
            return nextMoves;
          });
          setClueTileIdx(null);
        }
        return nextBoard;
      }
      return prevBoard;
    });
  }, [gridSize, isSolving, hasShuffled, saveStats]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setShuffleDepth(newHistory.length);
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || history.length === 0) return;
    setHistory(prev => {
      const newHistory = [...prev];
      const last = newHistory.pop();
      if (last) {
        setBoard(last);
        setMoves(m => Math.max(0, m - 1));
        setClueTileIdx(null);
        setIsGameFinished(false);
      }
      return newHistory;
    });
  }, [isSolving, history.length]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && history.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GridSize, TileShape } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  movingTileIdx: number | null;
  clueTileIdx: number | null;
  showNumbers: boolean;
  tileShape: TileShape;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = React.memo(({ 
  board, gridSize, imageUrl, onTileClick, spacing, movingTileIdx, clueTileIdx, showNumbers, tileShape 
}) => {
  const [dimensions, setDimensions] = useState({ width: 300, height: 300 });

  useEffect(() => {
    const handleResize = () => {
      const maxW = window.innerWidth - 32;
      const maxH = window.innerHeight - 360;
      const targetWidthLimit = Math.min(maxW, 420);
      const tileS = Math.floor((targetWidthLimit - (gridSize.cols - 1) * spacing) / gridSize.cols);
      let calculatedHeight = tileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      let calculatedWidth = tileS * gridSize.cols + (gridSize.cols - 1) * spacing;

      if (calculatedHeight > maxH) {
          const scaledTileS = Math.floor((maxH - (gridSize.rows - 1) * spacing) / gridSize.rows);
          calculatedWidth = scaledTileS * gridSize.cols + (gridSize.cols - 1) * spacing;
          calculatedHeight = scaledTileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      }
      setDimensions({ width: calculatedWidth, height: calculatedHeight });
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [gridSize.cols, gridSize.rows, spacing]);

  const { width: boardWidth, height: boardHeight } = dimensions;
  const tileW = (boardWidth - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileH = (boardHeight - (gridSize.rows - 1) * spacing) / gridSize.rows;
  const borderRadius = tileShape === 'rounded' ? '12px' : '0px';

  return (
    <div 
      className="relative select-none"
      style={{ 
        width: boardWidth, 
        height: boardHeight,
        perspective: '1200px',
        transformStyle: 'preserve-3d',
        touchAction: 'none'
      }}
    >
      {board.map((val, idx) => {
        if (val === board.length - 1) return null;

        const row = Math.floor(idx / gridSize.cols);
        const col = idx % gridSize.cols;
        const origRow = Math.floor(val / gridSize.cols);
        const origCol = val % gridSize.cols;

        // Using Math.round to prevent sub-pixel rendering jitters on Android
        const left = Math.round(col * (tileW + spacing));
        const top = Math.round(row * (tileH + spacing));

        const isMoving = movingTileIdx === idx;
        const isClue = clueTileIdx === idx;
        const bgX = gridSize.cols > 1 ? (origCol / (gridSize.cols - 1)) * 100 : 0;
        const bgY = gridSize.rows > 1 ? (origRow / (gridSize.rows - 1)) * 100 : 0;

        return (
          <div
            key={val}
            onClick={() => onTileClick(idx)}
            className="absolute puzzle-tile-transition cursor-pointer overflow-hidden border border-white/10 shadow-lg group active:brightness-125 touch-manipulation"
            style={{
              width: Math.round(tileW),
              height: Math.round(tileH),
              transform: `translate3d(${left}px, ${top}px, 0) translateZ(0)`,
              borderRadius: borderRadius,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${bgX}% ${bgY}%`,
              backfaceVisibility: 'hidden',
              WebkitBackfaceVisibility: 'hidden',
              willChange: 'transform'
            }}
          >
            {showNumbers && (
              <div className="absolute top-1.5 left-1.5 bg-black/60 backdrop-blur-md rounded-md px-1.5 py-0.5 min-w-[1.2rem] text-center border border-white/10 pointer-events-none">
                <span className="text-[10px] font-black text-white/90">{val + 1}</span>
              </div>
            )}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none bg-amber-400/20">
                <div className="w-5 h-5 rounded-full bg-amber-400 shadow-[0_0_20px_rgba(251,191,36,1)] border-2 border-white clue-dot" />
              </div>
            )}
            {isMoving && (
              <div className="absolute inset-0 flex items-center justify-center bg-blue-400/30 border-2 border-blue-400 pointer-events-none">
                <div className="w-full h-full border-2 border-blue-400 animate-ping opacity-50" />
              </div>
            )}
            <div className="absolute inset-0 bg-white/0 group-hover:bg-white/5 active:bg-white/10 transition-colors pointer-events-none" />
          </div>
        );
      })}
    </div>
  );
});

export default PuzzleBoard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 4, cols: 4 }); }
    } else { initBoard({ rows: 4, cols: 4 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;
    setBoard(prevBoard => {
      const emptyIdx = prevBoard.indexOf(prevBoard.length - 1);
      if (isAdjacent(index, emptyIdx, gridSize)) {
        const nextBoard = [...prevBoard];
        [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

        setHistory(prevHistory => {
          const previousState = prevHistory[prevHistory.length - 1];
          const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
          return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, prevBoard];
        });

        if (!silent) {
          setMoves(m => {
            const nextMoves = m + 1;
            if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
              setIsGameFinished(true);
              saveStats(nextMoves, secondsRef.current, gridSize);
            }
            return nextMoves;
          });
          setClueTileIdx(null);
        }
        return nextBoard;
      }
      return prevBoard;
    });
  }, [gridSize, isSolving, hasShuffled, saveStats]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || history.length === 0) return;
    setHistory(prev => {
      const newHistory = [...prev];
      const last = newHistory.pop();
      if (last) {
        setBoard(last);
        setMoves(m => Math.max(0, m - 1));
        setClueTileIdx(null);
        setIsGameFinished(false);
      }
      return newHistory;
    });
  }, [isSolving, history.length]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && history.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { GridSize, TileShape } from '../types';

interface PuzzleBoardProps {
  board: number[];
  gridSize: GridSize;
  imageUrl: string;
  onTileClick: (index: number) => void;
  spacing: number;
  movingTileIdx: number | null;
  clueTileIdx: number | null;
  showNumbers: boolean;
  tileShape: TileShape;
}

const PuzzleBoard: React.FC<PuzzleBoardProps> = React.memo(({ 
  board, gridSize, imageUrl, onTileClick, spacing, movingTileIdx, clueTileIdx, showNumbers, tileShape 
}) => {
  const [dimensions, setDimensions] = useState({ width: 300, height: 300 });

  useEffect(() => {
    const handleResize = () => {
      const maxW = window.innerWidth - 32;
      const maxH = window.innerHeight - 360;
      const targetWidthLimit = Math.min(maxW, 420);
      const tileS = Math.floor((targetWidthLimit - (gridSize.cols - 1) * spacing) / gridSize.cols);
      let calculatedHeight = tileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      let calculatedWidth = tileS * gridSize.cols + (gridSize.cols - 1) * spacing;

      if (calculatedHeight > maxH) {
          const scaledTileS = Math.floor((maxH - (gridSize.rows - 1) * spacing) / gridSize.rows);
          calculatedWidth = scaledTileS * gridSize.cols + (gridSize.cols - 1) * spacing;
          calculatedHeight = scaledTileS * gridSize.rows + (gridSize.rows - 1) * spacing;
      }
      setDimensions({ width: calculatedWidth, height: calculatedHeight });
    };

    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [gridSize.cols, gridSize.rows, spacing]);

  const { width: boardWidth, height: boardHeight } = dimensions;
  const tileW = (boardWidth - (gridSize.cols - 1) * spacing) / gridSize.cols;
  const tileH = (boardHeight - (gridSize.rows - 1) * spacing) / gridSize.rows;
  const borderRadius = tileShape === 'rounded' ? '12px' : '0px';

  return (
    <div 
      className="relative select-none"
      style={{ 
        width: Math.round(boardWidth), 
        height: Math.round(boardHeight),
        perspective: '1200px',
        transformStyle: 'preserve-3d',
        touchAction: 'none'
      }}
    >
      {board.map((val, idx) => {
        if (val === board.length - 1) return null;

        const row = Math.floor(idx / gridSize.cols);
        const col = idx % gridSize.cols;
        const origRow = Math.floor(val / gridSize.cols);
        const origCol = val % gridSize.cols;

        // Use Math.round to force integer pixel positions and prevent sub-pixel jitters/blinking on Android
        const left = Math.round(col * (tileW + spacing));
        const top = Math.round(row * (tileH + spacing));

        const isMoving = movingTileIdx === idx;
        const isClue = clueTileIdx === idx;
        const bgX = gridSize.cols > 1 ? (origCol / (gridSize.cols - 1)) * 100 : 0;
        const bgY = gridSize.rows > 1 ? (origRow / (gridSize.rows - 1)) * 100 : 0;

        return (
          <div
            key={val}
            onClick={() => onTileClick(idx)}
            className="absolute puzzle-tile-transition cursor-pointer overflow-hidden border border-white/10 shadow-lg group active:brightness-125 touch-manipulation"
            style={{
              width: Math.round(tileW),
              height: Math.round(tileH),
              transform: `translate3d(${left}px, ${top}px, 0) translateZ(0)`,
              borderRadius: borderRadius,
              backgroundImage: `url(${imageUrl})`,
              backgroundSize: `${gridSize.cols * 100}% ${gridSize.rows * 100}%`,
              backgroundPosition: `${bgX}% ${bgY}%`,
              backfaceVisibility: 'hidden',
              WebkitBackfaceVisibility: 'hidden',
              willChange: 'transform'
            }}
          >
            {showNumbers && (
              <div className="absolute top-1.5 left-1.5 bg-black/60 backdrop-blur-md rounded-md px-1.5 py-0.5 min-w-[1.2rem] text-center border border-white/10 pointer-events-none">
                <span className="text-[10px] font-black text-white/90">{val + 1}</span>
              </div>
            )}
            {isClue && (
              <div className="absolute inset-0 flex items-center justify-center pointer-events-none bg-amber-400/20">
                <div className="w-5 h-5 rounded-full bg-amber-400 shadow-[0_0_20px_rgba(251,191,36,1)] border-2 border-white clue-dot" />
              </div>
            )}
            {isMoving && (
              <div className="absolute inset-0 flex items-center justify-center bg-blue-400/30 border-2 border-blue-400 pointer-events-none">
                <div className="w-full h-full border-2 border-blue-400 animate-ping opacity-50" />
              </div>
            )}
            <div className="absolute inset-0 bg-white/0 group-hover:bg-white/5 active:bg-white/10 transition-colors pointer-events-none" />
          </div>
        );
      })}
    </div>
  );
});

export default PuzzleBoard;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 3, cols: 3 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 3, cols: 3 }); }
    } else { initBoard({ rows: 3, cols: 3 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    // Only save state if initial load from storage is already completed to avoid overwriting with defaults
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;
    setBoard(prevBoard => {
      const emptyIdx = prevBoard.indexOf(prevBoard.length - 1);
      if (isAdjacent(index, emptyIdx, gridSize)) {
        const nextBoard = [...prevBoard];
        [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

        setHistory(prevHistory => {
          const previousState = prevHistory[prevHistory.length - 1];
          const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
          return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, prevBoard];
        });

        if (!silent) {
          setMoves(m => {
            const nextMoves = m + 1;
            if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
              setIsGameFinished(true);
              saveStats(nextMoves, secondsRef.current, gridSize);
            }
            return nextMoves;
          });
          setClueTileIdx(null);
        }
        return nextBoard;
      }
      return prevBoard;
    });
  }, [gridSize, isSolving, hasShuffled, saveStats]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || history.length === 0) return;
    setHistory(prev => {
      const newHistory = [...prev];
      const last = newHistory.pop();
      if (last) {
        setBoard(last);
        setMoves(m => Math.max(0, m - 1));
        setClueTileIdx(null);
        setIsGameFinished(false);
      }
      return newHistory;
    });
  }, [isSolving, history.length]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && history.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 3, cols: 3 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  // Sync Target moves with current path history
  useEffect(() => {
    if (hasShuffled) {
      setRequiredMoves(history.length);
    } else {
      setRequiredMoves(0);
    }
  }, [history.length, hasShuffled]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 3, cols: 3 }); }
    } else { initBoard({ rows: 3, cols: 3 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;
    setBoard(prevBoard => {
      const emptyIdx = prevBoard.indexOf(prevBoard.length - 1);
      if (isAdjacent(index, emptyIdx, gridSize)) {
        const nextBoard = [...prevBoard];
        [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];

        setHistory(prevHistory => {
          const previousState = prevHistory[prevHistory.length - 1];
          const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
          return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, prevBoard];
        });

        if (!silent) {
          setMoves(m => {
            const nextMoves = m + 1;
            if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
              setIsGameFinished(true);
              saveStats(nextMoves, secondsRef.current, gridSize);
            }
            return nextMoves;
          });
          setClueTileIdx(null);
        }
        return nextBoard;
      }
      return prevBoard;
    });
  }, [gridSize, isSolving, hasShuffled, saveStats]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || history.length === 0) return;
    setHistory(prev => {
      const newHistory = [...prev];
      const last = newHistory.pop();
      if (last) {
        setBoard(last);
        setMoves(m => Math.max(0, m - 1));
        setClueTileIdx(null);
        setIsGameFinished(false);
      }
      return newHistory;
    });
  }, [isSolving, history.length]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && history.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission Accomplished</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

interface UndoStep {
  board: number[];
  history: number[][];
}

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 3, cols: 3 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [undoStack, setUndoStack] = useState<UndoStep[]>([]);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  // Sync Target moves with current path history
  useEffect(() => {
    if (hasShuffled) {
      setRequiredMoves(history.length);
    } else {
      setRequiredMoves(0);
    }
  }, [history.length, hasShuffled]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setUndoStack([]);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setUndoStack(parsed.undoStack || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 3, cols: 3 }); }
    } else { initBoard({ rows: 3, cols: 3 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, undoStack, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, undoStack]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;

    const emptyIdx = board.indexOf(board.length - 1);
    if (!isAdjacent(index, emptyIdx, gridSize)) return;

    // Snapshot current state for undo stack before making the move
    if (!silent) {
      setUndoStack(prev => [...prev, { board: [...board], history: [...history] }]);
    }

    const nextBoard = [...board];
    [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];
    setBoard(nextBoard);

    setHistory(prevHistory => {
      const previousState = prevHistory[prevHistory.length - 1];
      const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
      return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, board];
    });

    if (!silent) {
      setMoves(m => {
        const nextMoves = m + 1;
        if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
          setIsGameFinished(true);
          saveStats(nextMoves, secondsRef.current, gridSize);
        }
        return nextMoves;
      });
      setClueTileIdx(null);
    }
  }, [gridSize, isSolving, hasShuffled, saveStats, board, history]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setUndoStack([]); // Clear user undo stack on new game
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || undoStack.length === 0) return;

    const lastStep = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setBoard(lastStep.board);
    setHistory(lastStep.history);
    setMoves(m => Math.max(0, m - 1));
    setClueTileIdx(null);
    setIsGameFinished(false);
  }, [isSolving, undoStack]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden p-4 md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && undoStack.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission AccomplISHED</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState, useEffect, useRef, useCallback } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

interface UndoStep {
  board: number[];
  history: number[][];
}

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 3, cols: 3 });
  const [moves, setMoves] = useState(0);
  const [requiredMoves, setRequiredMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState<TileShape>('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [undoStack, setUndoStack] = useState<UndoStep[]>([]);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  // Sync Target moves with current path history
  useEffect(() => {
    if (hasShuffled) {
      setRequiredMoves(history.length);
    } else {
      setRequiredMoves(0);
    }
  }, [history.length, hasShuffled]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setRequiredMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setUndoStack([]);
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setRequiredMoves(parsed.requiredMoves || 0);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setUndoStack(parsed.undoStack || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 3, cols: 3 }); }
    } else { initBoard({ rows: 3, cols: 3 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, requiredMoves, imageUrl, gridSize, 
        history, undoStack, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, requiredMoves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, undoStack]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;

    const emptyIdx = board.indexOf(board.length - 1);
    if (!isAdjacent(index, emptyIdx, gridSize)) return;

    // Snapshot current state for undo stack before making the move
    if (!silent) {
      setUndoStack(prev => [...prev, { board: [...board], history: [...history] }]);
    }

    const nextBoard = [...board];
    [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];
    setBoard(nextBoard);

    setHistory(prevHistory => {
      const previousState = prevHistory[prevHistory.length - 1];
      const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
      return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, board];
    });

    if (!silent) {
      setMoves(m => {
        const nextMoves = m + 1;
        if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
          setIsGameFinished(true);
          saveStats(nextMoves, secondsRef.current, gridSize);
        }
        return nextMoves;
      });
      setClueTileIdx(null);
    }
  }, [gridSize, isSolving, hasShuffled, saveStats, board, history]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setUndoStack([]); // Clear user undo stack on new game
    setBoard(curr);
    setMoves(0);
    setRequiredMoves(newHistory.length);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || undoStack.length === 0) return;

    const lastStep = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setBoard(lastStep.board);
    setHistory(lastStep.history);
    setMoves(m => Math.max(0, m - 1));
    setClueTileIdx(null);
    setIsGameFinished(false);
  }, [isSolving, undoStack]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished || !hasShuffled || history.length === 0) return;
    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }
    if (isSolved(board) || !hasShuffled) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden pt-[max(1rem,env(safe-area-inset-top))] pb-[max(1rem,env(safe-area-inset-bottom))] pl-[max(1rem,env(safe-area-inset-left))] pr-[max(1rem,env(safe-area-inset-right))] md:p-12">
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg></button>
                <label className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer"><svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg><input type="file" accept="image/*" onChange={pickImage} className="hidden" /></label>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: requiredMoves || '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>
      <div className="flex items-center justify-center mb-10">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>
      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && undoStack.length > 0} />
      </div>
      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission AccomplISHED</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                    <p className="text-[9px] text-slate-500 font-medium tracking-tight mt-2 opacity-50">viswanatham@gmail.com</p>
                </div>
            </div>
        </div>
      )}
      <Menu isOpen={isMenuOpen} onClose={() => setIsMenuOpen(false)} gridSize={gridSize} setGridSize={(s) => { setGridSize(s); initBoard(s); }} difficulty={difficulty} setDifficulty={setDifficulty} spacing={spacing} setSpacing={setSpacing} showNumbers={showNumbers} setShowNumbers={setShowNumbers} tileShape={tileShape} setTileShape={setTileShape} imageHistory={imageHistory} onSelectHistoryImage={setImageUrl} onPickImage={pickImage} onLoadSaved={loadSavedState} />
    </div>
  );
};

export default App;

import React, { useState } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from '../types';

interface MenuProps {
  isOpen: boolean;
  onClose: () => void;
  gridSize: GridSize;
  setGridSize: (s: GridSize) => void;
  difficulty: Difficulty;
  setDifficulty: (d: Difficulty) => void;
  spacing: number;
  setSpacing: (v: number) => void;
  showNumbers: boolean;
  setShowNumbers: (v: boolean) => void;
  tileShape: TileShape;
  setTileShape: (s: TileShape) => void;
  imageHistory: string[];
  onSelectHistoryImage: (url: string) => void;
  onPickImage: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onLoadSaved: () => void;
}

