        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setUndoStack([]); 
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setUndoStack(parsed.undoStack || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 4, cols: 4 }); }
    } else { initBoard({ rows: 4, cols: 4 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, imageUrl, gridSize, 
        history, undoStack, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, undoStack]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;

    // Check if user has shuffled before playing
    if (!hasShuffled && !silent) {
      alert("Please shuffle the picture before starting the game!");
      return;
    }

    const emptyIdx = board.indexOf(board.length - 1);
    if (!isAdjacent(index, emptyIdx, gridSize)) return;

    if (!silent) {
      setUndoStack(prev => [...prev, { board: [...board], history: [...history] }]);
    }

    const nextBoard = [...board];
    [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];
    setBoard(nextBoard);

    setHistory(prevHistory => {
      const previousState = prevHistory[prevHistory.length - 1];
      const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
      return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, board];
    });

    if (!silent) {
      setMoves(m => {
        const nextMoves = m + 1;
        if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
          setIsGameFinished(true);
          saveStats(nextMoves, secondsRef.current, gridSize);
        }
        return nextMoves;
      });
      setClueTileIdx(null);
    }
  }, [gridSize, isSolving, hasShuffled, saveStats, board, history]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setUndoStack([]); 
    setBoard(curr);
    setMoves(0);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || undoStack.length === 0) return;

    const lastStep = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setBoard(lastStep.board);
    setHistory(lastStep.history);
    setMoves(m => Math.max(0, m - 1));
    setClueTileIdx(null);
    setIsGameFinished(false);
  }, [isSolving, undoStack]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished) return;

    if (!hasShuffled) {
      alert("Please shuffle the picture before getting a clue!");
      return;
    }

    if (history.length === 0) return;

    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }

    if (!hasShuffled) {
      alert("Please shuffle the puzzle before using the solve feature!");
      return;
    }

    if (isSolved(board)) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory]);

  return (
    <div 
      className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden pb-[max(1.5rem,env(safe-area-inset-bottom))] pl-[max(1.5rem,env(safe-area-inset-left))] pr-[max(1.5rem,env(safe-area-inset-right))] md:p-12"
      style={{
        paddingTop: isIOS 
          ? 'calc(max(1.5rem, env(safe-area-inset-top)) + 0.75rem)' 
          : 'max(1.5rem, env(safe-area-inset-top))'
      }}
    >
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
                </button>
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer">
                  <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>
                </button>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: currentTarget !== null ? currentTarget : '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>

      <div className="flex items-center justify-center mb-10 relative">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>

      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && undoStack.length > 0} />
      </div>

      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission AccomplISHED</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                </div>
            </div>
        </div>
      )}

      <Menu 
        isOpen={isMenuOpen} 
        onClose={() => setIsMenuOpen(false)} 
        gridSize={gridSize} 
        setGridSize={(s) => { setGridSize(s); initBoard(s); }} 
        difficulty={difficulty} 
        setDifficulty={setDifficulty} 
        spacing={spacing} 
        setSpacing={setSpacing} 
        showNumbers={showNumbers} 
        setShowNumbers={setShowNumbers} 
        tileShape={tileShape} 
        setTileShape={setTileShape} 
        imageHistory={imageHistory} 
        onSelectHistoryImage={setImageUrl} 
        onPickImage={pickImage} 
        onLoadSaved={loadSavedState}
      />
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from '../types';

interface MenuProps {
  isOpen: boolean;
  onClose: () => void;
  gridSize: GridSize;
  setGridSize: (s: GridSize) => void;
  difficulty: Difficulty;
  setDifficulty: (d: Difficulty) => void;
  spacing: number;
  setSpacing: (v: number) => void;
  showNumbers: boolean;
  setShowNumbers: (v: boolean) => void;
  tileShape: TileShape;
  setTileShape: (s: TileShape) => void;
  imageHistory: string[];
  onSelectHistoryImage: (url: string) => void;
  onPickImage: (e: React.ChangeEvent<HTMLInputElement>) => void;
  onLoadSaved: () => void;
}

const Menu: React.FC<MenuProps> = ({
  isOpen, onClose, gridSize, setGridSize, difficulty, setDifficulty,
  spacing, setSpacing, showNumbers, setShowNumbers, tileShape, setTileShape,
  imageHistory, onSelectHistoryImage, onPickImage, onLoadSaved
}) => {
  const [activeSubView, setActiveSubView] = useState<'main' | 'instructions' | 'about'>('main');
  const [isUploadExpanded, setIsUploadExpanded] = useState(false);

  const version = useMemo(() => {
    // Current date: 2025-05-22
    const yy = "25";
    const mm = "05";
    const dd = "22";
    const iteration = "5"; 
    return `${yy}${mm}${dd}.${iteration}`;
  }, []);

  if (!isOpen) return null;

  const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
  const bestStats = [...stats].sort((a, b) => a.moves - b.moves).slice(0, 10);

  const handleClose = () => {
    setActiveSubView('main');
    setIsUploadExpanded(false);
    onClose();
  };

  const renderInstructions = () => (
    <div className="flex flex-col h-full animate-pop">
      <div className="flex items-center gap-4 mb-8">
        <button 
          onClick={() => setActiveSubView('main')}
          className="p-2 hover:bg-slate-800 rounded-lg text-blue-400 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="3" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <h2 className="text-xl font-black tracking-tighter text-white uppercase">How to Play</h2>
      </div>

      <div className="space-y-6 text-[12px] leading-relaxed text-slate-400 overflow-y-auto pr-2">
          <p><span className="text-blue-400 font-black block mb-1 uppercase tracking-wider">01. START</span> Hit <span className="text-white font-bold">Shuffle</span> to scramble the tiles. The timer and move counter begin on your first move.</p>
          <p><span className="text-blue-400 font-black block mb-1 uppercase tracking-wider">02. NAVIGATION</span> Tap tiles next to the empty space to move them. Toggle <span className="text-white font-bold">Show Numbers</span> if the image is too difficult.</p>
          <p><span className="text-blue-400 font-black block mb-1 uppercase tracking-wider">03. PERSONALIZE</span> Change <span className="text-white font-bold">Tile Spacing</span> for a cleaner look or switch between <span className="text-white font-bold">Square</span> and <span className="text-white font-bold">Rounded</span> tile shapes.</p>
          <p><span className="text-blue-400 font-black block mb-1 uppercase tracking-wider">04. MATRIX</span> Choose your grid size (3x3, 4x4, 5x5) to adjust the difficulty level.</p>
          <p><span className="text-blue-400 font-black block mb-1 uppercase tracking-wider">05. HALL OF FAME</span> Your lowest move counts are saved locally for each grid size. Try to beat your best!</p>
      </div>

      <button 
        onClick={() => setActiveSubView('main')}
        className="mt-auto py-4 bg-slate-800 hover:bg-slate-750 text-white rounded-xl font-black text-[10px] tracking-[0.2em] transition-all uppercase"
      >
        Back to Menu
      </button>
    </div>
  );

  const renderAbout = () => (
    <div className="flex flex-col h-full animate-pop">
      <div className="flex items-center gap-4 mb-8">
        <button 
          onClick={() => setActiveSubView('main')}
          className="p-2 hover:bg-slate-800 rounded-lg text-blue-400 transition-colors"
        >
          <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="m15 18-6-6 6-6"/></svg>
        </button>
        <h2 className="text-xl font-black tracking-tighter text-white uppercase">About</h2>
      </div>

      <div className="flex flex-col items-center justify-center flex-1 text-center space-y-4">
          <div className="w-16 h-16 bg-blue-500/10 rounded-3xl flex items-center justify-center border border-blue-500/20 mb-4">
              <svg xmlns="http://www.w3.org/2000/svg" width="32" height="32" viewBox="0 0 24 24" fill="none" stroke="#3b82f6" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M12 3v19"/><path d="M5 8h14"/><path d="M15 21a2 2 0 0 0 2-2V5a2 2 0 0 0-2-2H9a2 2 0 0 0-2 2v14a2 2 0 0 0 2 2h6Z"/></svg>
          </div>
          <h1 className="text-2xl font-black text-white tracking-tighter uppercase">R3AL PUZZLE</h1>
          <p className="text-blue-400 font-bold tracking-widest text-[10px] uppercase">For grand kids</p>
          <div className="w-8 h-px bg-slate-800 my-4" />
          <p className="text-slate-400 text-xs font-medium">Viswanatham@gmail.com</p>
          <p className="text-slate-600 text-[10px] font-black tracking-[0.2em] mt-8 uppercase">{version}</p>
      </div>

      <button 
        onClick={() => setActiveSubView('main')}
        className="mt-auto py-4 bg-slate-800 hover:bg-slate-750 text-white rounded-xl font-black text-[10px] tracking-[0.2em] transition-all uppercase"
      >
        Back to Menu
      </button>
    </div>
  );

  return (
    <div className="fixed inset-0 z-50 flex overflow-hidden">
      <div className="absolute inset-0 bg-black/60 backdrop-blur-sm" onClick={handleClose} />
      <div className="relative w-80 h-full bg-slate-900 shadow-2xl pt-[max(1.5rem,env(safe-area-inset-top))] pb-[max(1.5rem,env(safe-area-inset-bottom))] pl-[max(1.5rem,env(safe-area-inset-left))] pr-6 flex flex-col gap-6 animate-menu border-r border-white/5 overflow-y-auto">

        {activeSubView === 'instructions' ? renderInstructions() : 
         activeSubView === 'about' ? renderAbout() : (
          <>
            <div className="flex items-center justify-between">
                <h2 className="text-xl font-black tracking-tighter text-white uppercase">Game Menu</h2>
                <button onClick={handleClose} className="p-2 hover:bg-slate-800 rounded-lg text-slate-400">
                    <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><line x1="18" y1="6" x2="6" y2="18"/><line x1="6" y1="6" x2="18" y2="18"/></svg>
                </button>
            </div>

            {/* Navigation links */}
            <div className="grid grid-cols-1 gap-2">
                <button onClick={() => setActiveSubView('instructions')} className="flex items-center justify-between p-4 bg-slate-800/40 hover:bg-slate-800 rounded-2xl border border-white/5 group transition-all">
                    <span className="text-xs font-black text-slate-300 uppercase tracking-tight">How to play</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-slate-600 group-hover:text-blue-400 transition-colors"><path d="m9 18 6-6-6-6"/></svg>
                </button>
                <button onClick={() => setActiveSubView('about')} className="flex items-center justify-between p-4 bg-slate-800/40 hover:bg-slate-800 rounded-2xl border border-white/5 group transition-all">
                    <span className="text-xs font-black text-slate-300 uppercase tracking-tight">About game</span>
                    <svg xmlns="http://www.w3.org/2000/svg" width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-slate-600 group-hover:text-blue-400 transition-colors"><path d="m9 18 6-6-6-6"/></svg>
                </button>
            </div>

            {/* Pick a Picture Section (Below About Game) */}
            <section className="bg-slate-800/20 p-4 rounded-3xl border border-white/5 flex flex-col gap-4">
                <h3 className="text-[10px] font-black text-slate-500 uppercase tracking-[0.2em]">Pick a Picture</h3>

                <div className="flex flex-col gap-3">
                    <button 
                        onClick={() => setIsUploadExpanded(!isUploadExpanded)}
                        className={`flex items-center justify-center gap-3 w-full py-4 rounded-2xl font-black text-[10px] tracking-widest uppercase transition-all active:scale-95 shadow-lg border ${
                            isUploadExpanded 
                            ? 'bg-blue-600 border-blue-400 text-white' 
                            : 'bg-slate-800 border-slate-700 text-slate-400'
                        }`}
                    >
                        <svg xmlns="http://www.w3.org/2000/svg" width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>
                        Gallery Upload
                    </button>

                    {isUploadExpanded && (
                        <div className="grid grid-cols-2 gap-3 animate-pop">
                            <label className="flex flex-col items-center justify-center gap-2 py-5 bg-slate-800 border border-slate-700 rounded-2xl hover:bg-slate-750 transition-all cursor-pointer group active:scale-95">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-slate-500 group-hover:text-blue-400 transition-colors"><path d="M23 19a2 2 0 0 1-2 2H3a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h4l2-3h6l2 3h4a2 2 0 0 1 2 2z"/><circle cx="12" cy="13" r="4"/></svg>
                                <span className="text-[9px] text-slate-400 font-black tracking-widest uppercase">Camera</span>
                                <input type="file" accept="image/*" capture="environment" onChange={(e) => { onPickImage(e); handleClose(); }} className="hidden" />
                            </label>
                            <label className="flex flex-col items-center justify-center gap-2 py-5 bg-slate-800 border border-slate-700 rounded-2xl hover:bg-slate-750 transition-all cursor-pointer group active:scale-95">
                                <svg xmlns="http://www.w3.org/2000/svg" width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round" className="text-slate-500 group-hover:text-blue-400 transition-colors"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>
                                <span className="text-[9px] text-slate-400 font-black tracking-widest uppercase">Browse</span>
                                <input type="file" accept="image/*" onChange={(e) => { onPickImage(e); handleClose(); }} className="hidden" />
                            </label>
                        </div>
                    )}

                    {imageHistory.length > 0 && (
                        <div className="flex flex-col gap-2 mt-2">
                            <span className="text-[8px] font-black text-slate-500 uppercase tracking-widest ml-1">Recent Pictures</span>
                            <div className="flex gap-2.5 overflow-x-auto pb-1 scrollbar-hide">
                                {imageHistory.map((url, i) => (
                                    <button 
                                        key={i} 
                                        onClick={() => { onSelectHistoryImage(url); handleClose(); }}
                                        className="flex-shrink-0 w-14 h-14 rounded-xl bg-cover bg-center border border-slate-700 active:scale-90 transition-all hover:border-blue-500 shadow-xl"
                                        style={{ backgroundImage: `url(${url})` }}
                                    />
                                ))}
                            </div>
                        </div>
                    )}
                </div>
            </section>

            {/* Toggles */}
            <section className="flex items-center justify-between p-4 bg-slate-800/50 rounded-2xl border border-white/5">
                <span className="text-xs font-black text-slate-300 tracking-tight uppercase">Show Numbers</span>
                <button 
                    onClick={() => setShowNumbers(!showNumbers)}
                    className={`relative w-12 h-6 rounded-full transition-colors ${showNumbers ? 'bg-blue-600' : 'bg-slate-700'}`}
                >
                    <div className={`absolute top-1 w-4 h-4 bg-white rounded-full transition-all ${showNumbers ? 'left-7' : 'left-1'}`} />
                </button>
            </section>

            {/* Matrix Size (Below Show Numbers) */}
            <section>
                <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Matrix Size</h3>
                <div className="grid grid-cols-3 gap-2">
                    {[3, 4, 5].map(size => (
                        <button 
                            key={size} 
                            onClick={() => setGridSize({ rows: size, cols: size })}
                            className={`py-3 rounded-xl text-[10px] font-black transition-all border uppercase tracking-widest ${
                                gridSize.rows === size 
                                ? 'bg-blue-600 border-blue-400 text-white shadow-lg' 
                                : 'bg-slate-800 border-white/5 text-slate-400'
                            }`}
                        >
                            {size}X{size}
                        </button>
                    ))}
                </div>
            </section>

            {/* Tile Shape Selection */}
            <section>
                <h3 className="text-[10px] font-bold text-slate-500 uppercase tracking-[0.2em] mb-3">Tile Shape</h3>
                <div className="flex gap-2">
                    {(['square', 'rounded'] as TileShape[]).map(s => (
                        <button 
                            key={s} 
                            onClick={() => setTileShape(s)}
                            className={`flex-1 py-3 rounded-xl text-xs font-bold transition-all border uppercase tracking-widest ${
                                tileShape === s 
                                ? 'bg-blue-600 border-blue-400 text-white shadow-lg' 
                                : 'bg-slate-800 border-white/5 text-slate-400'
                            }`}
                        >
                            {s.toUpperCase()}
                        </button>
                    ))}
                </div>
            </section>

            {/* Persistence Actions */}
            <section>
                <button 
                    onClick={() => { onLoadSaved(); handleClose(); }}
                    className="w-full py-4 bg-blue-600/20 border border-blue-500/30 text-blue-400 rounded-xl font-black text-xs uppercase tracking-widest hover:bg-blue-600/30 transition-all active:scale-95"
                >
                    Load Saved State
                </button>
            </section>

            {/* Stats Display */}
            <section className="mt-auto border-t border-white/5 pt-6 pb-4">
                <h3 className="text-[10px] font-bold text-blue-400 uppercase tracking-[0.2em] mb-4">Hall of Fame</h3>
                <div className="space-y-2 max-h-40 overflow-y-auto pr-1">
                    {bestStats.length === 0 ? (
                        <p className="text-[10px] text-slate-600 italic text-center py-4">No records yet. Win a game to show up here!</p>
                    ) : (
                        bestStats.map((s, i) => (
                            <div key={i} className="flex justify-between items-center bg-slate-800/40 p-3 rounded-xl text-[10px] border border-white/5">
                                <div className="flex flex-col">
                                    <span className="font-bold text-slate-300 uppercase">{s.gridSize} Grid</span>
                                    <span className="text-slate-600 uppercase">{s.date}</span>
                                </div>
                                <div className="text-right">
                                    <div className="text-blue-400 font-black uppercase">{s.moves} Moves</div>
                                    <div className="text-slate-500 uppercase">{s.time}S</div>
                                </div>
                            </div>
                        ))
                    )}
                </div>
            </section>
          </>
        )}
      </div>
    </div>
  );
};

export default Menu;

import React, { useState, useEffect, useRef, useCallback, useMemo } from 'react';
import { GridSize, Difficulty, StatsEntry, TileShape } from './types';
import { isAdjacent, getMovableIndices, isSolved } from './services/puzzleLogic';
import PuzzleBoard from './components/PuzzleBoard';
import Controls from './components/Controls';
import Menu from './components/Menu';

const DEFAULT_IMAGE = 'https://picsum.photos/id/237/800/800';

interface UndoStep {
  board: number[];
  history: number[][];
}

const App: React.FC = () => {
  const [board, setBoard] = useState<number[]>([]);
  // Default to 4x4 as per latest requirement
  const [gridSize, setGridSize] = useState<GridSize>({ rows: 4, cols: 4 });
  const [moves, setMoves] = useState(0);
  const [seconds, setSeconds] = useState(0);
  const [imageUrl, setImageUrl] = useState(DEFAULT_IMAGE);
  const [difficulty, setDifficulty] = useState<Difficulty>('Easy');
  const [spacing, setSpacing] = useState(2);
  const [showNumbers, setShowNumbers] = useState(true);
  const [tileShape, setTileShape] = useState('square');
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const [isSolving, setIsSolving] = useState(false);
  const [movingTileIdx, setMovingTileIdx] = useState<number | null>(null);
  const [clueTileIdx, setClueTileIdx] = useState<number | null>(null);
  const [isGameFinished, setIsGameFinished] = useState(false);
  const [imageHistory, setImageHistory] = useState<string[]>([]);
  const [bestMoves, setBestMoves] = useState<number | null>(null);
  const [hasShuffled, setHasShuffled] = useState(false);
  const [history, setHistory] = useState<number[][]>([]);
  const [undoStack, setUndoStack] = useState<UndoStep[]>([]);
  const [isIOS, setIsIOS] = useState(false);

  const timerRef = useRef<number | null>(null);
  const secondsRef = useRef(0);
  const abortSolvingRef = useRef(false);
  const isInitialLoadDone = useRef(false);

  useEffect(() => {
    const userAgent = window.navigator.userAgent.toLowerCase();
    const isIOSDevice = /iphone|ipad|ipod/.test(userAgent);
    setIsIOS(isIOSDevice);
  }, []);

  useEffect(() => { secondsRef.current = seconds; }, [seconds]);

  const currentTarget = useMemo(() => hasShuffled ? history.length : null, [hasShuffled, history.length]);

  const updateBestMoves = useCallback((size: GridSize) => {
    try {
      const rawStats = localStorage.getItem('puzzle_stats');
      if (!rawStats) {
        setBestMoves(null);
        return;
      }
      const stats: StatsEntry[] = JSON.parse(rawStats);
      const gridKey = `${size.rows}x${size.cols}`;
      const relevant = stats.filter(s => s.gridSize === gridKey);
      if (relevant.length > 0) {
        const min = Math.min(...relevant.map(r => r.moves));
        setBestMoves(min);
      } else {
        setBestMoves(null);
      }
    } catch (e) { setBestMoves(null); }
  }, []);

  const initBoard = useCallback((size: GridSize) => {
    const newBoard = Array.from({ length: size.rows * size.cols }, (_, i) => i);
    setBoard(newBoard);
    setMoves(0);
    setSeconds(0);
    setHasShuffled(false);
    setHistory([]);
    setUndoStack([]); 
    setIsGameFinished(false);
    setClueTileIdx(null);
    setMovingTileIdx(null);
    setIsSolving(false);
    abortSolvingRef.current = false;
    updateBestMoves(size);
  }, [updateBestMoves]);

  const loadSavedState = useCallback(() => {
    const lastData = localStorage.getItem('puzzle_current_state_data');
    const lastSeconds = localStorage.getItem('puzzle_current_seconds');
    if (lastData) {
        try {
            const parsed = JSON.parse(lastData);
            setBoard(parsed.board);
            setMoves(parsed.moves);
            setSeconds(lastSeconds ? parseInt(lastSeconds, 10) : 0);
            setImageUrl(parsed.imageUrl || DEFAULT_IMAGE);
            setGridSize(parsed.gridSize);
            setHistory(parsed.history || []);
            setUndoStack(parsed.undoStack || []);
            setDifficulty(parsed.difficulty || 'Easy');
            setSpacing(parsed.spacing || 2);
            setShowNumbers(parsed.showNumbers ?? true);
            setTileShape(parsed.tileShape || 'square');
            setHasShuffled(parsed.hasShuffled ?? false);
            updateBestMoves(parsed.gridSize);
            setIsGameFinished(isSolved(parsed.board) && parsed.hasShuffled && parsed.moves > 0);
        } catch(e) { initBoard({ rows: 4, cols: 4 }); }
    } else { initBoard({ rows: 4, cols: 4 }); }
  }, [initBoard, updateBestMoves]);

  useEffect(() => {
    if (!isInitialLoadDone.current) {
      const storedHistory = localStorage.getItem('puzzle_image_history');
      if (storedHistory) {
        try { setImageHistory(JSON.parse(storedHistory)); } catch (e) { setImageHistory([]); }
      }
      loadSavedState();
      isInitialLoadDone.current = true;
    }
  }, [loadSavedState]);

  useEffect(() => {
    if (isInitialLoadDone.current && board.length > 0) {
      const stateToSave = { 
        board, moves, imageUrl, gridSize, 
        history, undoStack, difficulty, spacing, showNumbers, tileShape, hasShuffled 
      };
      try { localStorage.setItem('puzzle_current_state_data', JSON.stringify(stateToSave)); } catch (e) {}
    }
  }, [board, moves, imageUrl, gridSize, difficulty, spacing, showNumbers, tileShape, hasShuffled, history, undoStack]);

  useEffect(() => {
    if (seconds > 0 && !isGameFinished) {
      try { localStorage.setItem('puzzle_current_seconds', seconds.toString()); } catch (e) {}
    }
  }, [seconds, isGameFinished]);

  const isTimerActive = moves > 0 && !isGameFinished && !isSolving;
  useEffect(() => {
    if (isTimerActive) {
      if (!timerRef.current) {
        timerRef.current = window.setInterval(() => setSeconds(s => s + 1), 1000);
      }
    } else if (timerRef.current) {
      clearInterval(timerRef.current);
      timerRef.current = null;
    }
    return () => { if (timerRef.current) clearInterval(timerRef.current); };
  }, [isTimerActive]);

  const saveStats = useCallback((m: number, t: number, s: GridSize) => {
    try {
      const stats: StatsEntry[] = JSON.parse(localStorage.getItem('puzzle_stats') || '[]');
      const entry: StatsEntry = { 
        date: new Date().toLocaleDateString(), 
        moves: m, 
        time: t, 
        gridSize: `${s.rows}x${s.cols}` 
      };
      const updated = [entry, ...stats].sort((a,b) => a.moves - b.moves).slice(0, 50);
      localStorage.setItem('puzzle_stats', JSON.stringify(updated));
    } catch (e) {}
    updateBestMoves(s);
  }, [updateBestMoves]);

  const handleMove = useCallback((index: number, silent = false) => {
    if (isSolving && !silent) return;

    // Check if user has shuffled before playing
    if (!hasShuffled && !silent) {
      alert("Please shuffle the picture before starting the game!");
      return;
    }

    const emptyIdx = board.indexOf(board.length - 1);
    if (!isAdjacent(index, emptyIdx, gridSize)) return;

    if (!silent) {
      setUndoStack(prev => [...prev, { board: [...board], history: [...history] }]);
    }

    const nextBoard = [...board];
    [nextBoard[index], nextBoard[emptyIdx]] = [nextBoard[emptyIdx], nextBoard[index]];
    setBoard(nextBoard);

    setHistory(prevHistory => {
      const previousState = prevHistory[prevHistory.length - 1];
      const isCorrectBacktrack = previousState && previousState.every((val, i) => val === nextBoard[i]);
      return isCorrectBacktrack ? prevHistory.slice(0, -1) : [...prevHistory, board];
    });

    if (!silent) {
      setMoves(m => {
        const nextMoves = m + 1;
        if (isSolved(nextBoard) && hasShuffled && nextMoves > 0) {
          setIsGameFinished(true);
          saveStats(nextMoves, secondsRef.current, gridSize);
        }
        return nextMoves;
      });
      setClueTileIdx(null);
    }
  }, [gridSize, isSolving, hasShuffled, saveStats, board, history]);

  const shuffle = useCallback(() => {
    if (isSolving) return;
    setIsGameFinished(false);
    let curr = Array.from({ length: gridSize.rows * gridSize.cols }, (_, i) => i);
    const shuffleCount = difficulty === 'Easy' ? 20 : difficulty === 'Medium' ? 50 : 150;
    let lastEmpty = -1;
    const newHistory: number[][] = [];

    for (let i = 0; i < shuffleCount; i++) {
      const emptyIdx = curr.indexOf(curr.length - 1);
      const movables = getMovableIndices(emptyIdx, gridSize).filter(idx => idx !== lastEmpty);
      const move = movables[Math.floor(Math.random() * movables.length)];
      newHistory.push([...curr]);
      [curr[emptyIdx], curr[move]] = [curr[move], curr[emptyIdx]];
      lastEmpty = emptyIdx;
    }

    setHistory(newHistory);
    setUndoStack([]); 
    setBoard(curr);
    setMoves(0);
    setSeconds(0);
    setClueTileIdx(null);
    setHasShuffled(true);
  }, [gridSize, difficulty, isSolving]);

  const undo = useCallback(() => {
    if (isSolving || undoStack.length === 0) return;

    const lastStep = undoStack[undoStack.length - 1];
    setUndoStack(prev => prev.slice(0, -1));
    setBoard(lastStep.board);
    setHistory(lastStep.history);
    setMoves(m => Math.max(0, m - 1));
    setClueTileIdx(null);
    setIsGameFinished(false);
  }, [isSolving, undoStack]);

  const getClue = useCallback(() => {
    if (isSolving || isGameFinished) return;

    if (!hasShuffled) {
      alert("Please shuffle the picture before getting a clue!");
      return;
    }

    if (history.length === 0) return;

    const previousState = history[history.length - 1];
    const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
    setClueTileIdx(emptyIdxInPrevious);
  }, [isSolving, isGameFinished, hasShuffled, history, board.length]);

  const solve = useCallback(async () => {
    if (isSolving) { abortSolvingRef.current = true; return; }

    if (!hasShuffled) {
      alert("Please shuffle the puzzle before using the solve feature!");
      return;
    }

    if (isSolved(board)) return;

    setIsSolving(true);
    abortSolvingRef.current = false;

    let currentHistory = [...history];
    let moveCounter = moves;

    while (currentHistory.length > 0 && !abortSolvingRef.current) {
      const previousState = currentHistory[currentHistory.length - 1];
      const emptyIdxInPrevious = previousState.indexOf(board.length - 1);
      setMovingTileIdx(emptyIdxInPrevious);
      await new Promise(r => setTimeout(r, 600));
      if (abortSolvingRef.current) break;

      const nextBoard = [...previousState];
      setBoard(nextBoard);
      currentHistory.pop();
      setHistory([...currentHistory]);

      moveCounter++;
      setMoves(moveCounter);
      setMovingTileIdx(null);

      if (isSolved(nextBoard)) {
          setIsGameFinished(true);
          saveStats(moveCounter, secondsRef.current, gridSize);
          break;
      }
    }
    setIsSolving(false);
  }, [board, hasShuffled, history, moves, gridSize, isSolving, saveStats]);

  const pickImage = useCallback((e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onload = (ev) => {
        const img = new Image();
        img.onload = () => {
            const canvas = document.createElement('canvas');
            const targetAspect = gridSize.cols / gridSize.rows;
            const imgAspect = img.width / img.height;
            let cropWidth, cropHeight, offsetX, offsetY;
            if (imgAspect > targetAspect) {
                cropHeight = img.height;
                cropWidth = img.height * targetAspect;
                offsetX = (img.width - cropWidth) / 2;
                offsetY = 0;
            } else {
                cropWidth = img.width;
                cropHeight = img.width / targetAspect;
                offsetX = 0;
                offsetY = (img.height - cropHeight) / 2;
            }
            const BASE_SIZE = 800;
            canvas.width = BASE_SIZE * targetAspect;
            canvas.height = BASE_SIZE;
            const ctx = canvas.getContext('2d');
            if (ctx) {
              ctx.drawImage(img, offsetX, offsetY, cropWidth, cropHeight, 0, 0, canvas.width, canvas.height);
              try {
                const dataUrl = canvas.toDataURL('image/jpeg', 0.85);
                setImageUrl(dataUrl);
                initBoard(gridSize); // Reset board and shuffle state when new image loaded
                const updated = [dataUrl, ...imageHistory.filter(x => x !== dataUrl)].slice(0, 5);
                setImageHistory(updated);
                localStorage.setItem('puzzle_image_history', JSON.stringify(updated));
              } catch (err) { localStorage.removeItem('puzzle_image_history'); }
            }
        };
        img.src = ev.target?.result as string;
      };
      reader.readAsDataURL(file);
    }
    e.target.value = '';
  }, [gridSize, imageHistory, initBoard]);

  const handleSelectHistoryImage = useCallback((url: string) => {
    setImageUrl(url);
    initBoard(gridSize); // Reset board and shuffle state when history image loaded
  }, [initBoard, gridSize]);

  return (
    <div 
      className="w-full h-full flex flex-col items-center justify-start overflow-y-auto overflow-x-hidden pb-[max(1.5rem,env(safe-area-inset-bottom))] pl-[max(1.5rem,env(safe-area-inset-left))] pr-[max(1.5rem,env(safe-area-inset-right))] md:p-12"
      style={{
        paddingTop: isIOS 
          ? 'calc(max(1.5rem, env(safe-area-inset-top)) + 0.75rem)' 
          : 'max(1.5rem, env(safe-area-inset-top))'
      }}
    >
      <div className="w-full max-w-[420px] mb-8 flex flex-col items-center">
        <div className="flex items-center justify-between w-full mb-8">
            <div className="flex items-center gap-2">
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 relative">
                    <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><circle cx="12" cy="12" r="1"/><circle cx="12" cy="5" r="1"/><circle cx="12" cy="19" r="1"/></svg>
                </button>
                <button onClick={() => setIsMenuOpen(true)} className="p-3.5 rounded-2xl bg-white/5 border border-white/5 hover:bg-white/10 text-slate-400 hover:text-white transition-all shadow-xl active:scale-90 cursor-pointer">
                  <svg xmlns="http://www.w3.org/2000/svg" width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>
                </button>
            </div>
            <h1 className="text-2xl font-black text-white/95 tracking-tighter uppercase flex items-center gap-2"><span className="opacity-30">R3AL</span><span className="text-blue-500 drop-shadow-[0_0_12px_rgba(59,130,246,0.4)]">PUZZLE</span></h1>
            <div className="flex items-center">
              <select value={difficulty} onChange={(e) => setDifficulty(e.target.value as Difficulty)} className="bg-slate-800/80 border border-white/10 rounded-xl px-2.5 py-2 text-[9px] font-black uppercase text-blue-400 outline-none appearance-none cursor-pointer hover:bg-slate-700 transition-colors shadow-lg min-w-[70px] text-center">
                <option value="Easy">Easy</option><option value="Medium">Medium</option><option value="Hard">Hard</option>
              </select>
            </div>
        </div>
        <div className="grid grid-cols-4 w-full gap-2.5">
            {[
                { label: 'Moves', val: moves, color: 'text-white' },
                { label: 'Target', val: currentTarget !== null ? currentTarget : '--', color: 'text-emerald-400' },
                { label: 'Best', val: bestMoves || '--', color: 'text-blue-400' },
                { label: 'Time', val: `${Math.floor(seconds/60)}:${(seconds%60).toString().padStart(2,'0')}`, color: 'text-white' }
            ].map((stat, i) => (
                <div key={i} className="stat-card flex flex-col items-center justify-center py-2.5 px-1 rounded-2xl">
                    <span className={`text-xs font-black leading-none mb-1.5 ${stat.color}`}>{stat.val}</span>
                    <span className="text-[6px] uppercase font-black text-slate-500 tracking-[0.15em]">{stat.label}</span>
                </div>
            ))}
        </div>
      </div>

      <div className="flex items-center justify-center mb-10 relative">
          <PuzzleBoard board={board} gridSize={gridSize} imageUrl={imageUrl} onTileClick={handleMove} spacing={spacing} movingTileIdx={movingTileIdx} clueTileIdx={clueTileIdx} showNumbers={showNumbers} tileShape={tileShape} />
      </div>

      <div className="w-full max-w-[420px] pb-12">
          <Controls onShuffle={shuffle} onSolve={solve} onClue={getClue} onUndo={undo} isSolving={isSolving} canUndo={!isSolving && undoStack.length > 0} />
      </div>

      {isGameFinished && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center bg-black/95 backdrop-blur-xl p-6">
            <div className="bg-slate-900 border border-slate-700/50 p-10 rounded-[3rem] shadow-2xl text-center w-full max-w-sm animate-pop relative overflow-hidden">
                <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-blue-500 via-indigo-500 to-blue-500" />
                <div className="w-20 h-20 bg-blue-500/10 rounded-full flex items-center justify-center mx-auto mb-8 border border-blue-500/30">
                    <svg xmlns="http://www.w3.org/2000/svg" width="40" height="40" viewBox="0 0 24 24" fill="none" stroke="#60a5fa" strokeWidth="2.5" strokeLinecap="round" strokeLinejoin="round"><path d="M6 9H4.5a2.5 2.5 0 0 1 0-5H6"/><path d="M18 9h1.5a2.5 2.5 0 0 0 0-5H18"/><path d="M4 22h16"/><path d="M10 14.66V17c0 .55-.47.98-.97 1.21C7.85 18.75 7 20.24 7 22"/><path d="M14 14.66V17c0 .55.47.98.97 1.21C16.15 18.75 17 20.24 17 22"/><path d="M18 2H6v7a6 6 0 0 0 12 0V2Z"/></svg>
                </div>
                <h2 className="text-2xl font-black mb-3 text-white uppercase tracking-tighter">Mission AccomplISHED</h2>
                <p className="text-slate-400 text-xs mb-10 font-medium">Completed in <span className="text-white font-bold">{moves}</span> moves.</p>
                <div className="flex flex-col gap-3">
                    <button onClick={shuffle} className="w-full py-5 bg-blue-600 hover:bg-blue-500 rounded-2xl font-black text-[10px] tracking-[0.2em] transition-all shadow-xl active:scale-95 text-white">RESTART MATRIX</button>
                    <button onClick={() => setIsGameFinished(false)} className="w-full py-5 bg-slate-800 hover:bg-slate-750 rounded-2xl font-bold text-[10px] text-slate-400 tracking-[0.2em] transition-all active:scale-95 uppercase">Dismiss</button>
                </div>
            </div>
        </div>
      )}

      <Menu 
        isOpen={isMenuOpen} 
        onClose={() => setIsMenuOpen(false)} 
        gridSize={gridSize} 
        setGridSize={(s) => { setGridSize(s); initBoard(s); }} 
        difficulty={difficulty} 
        setDifficulty={setDifficulty} 
        spacing={spacing} 
        setSpacing={setSpacing} 
        showNumbers={showNumbers} 
        setShowNumbers={setShowNumbers} 
        tileShape={tileShape} 
        setTileShape={setTileShape} 
        imageHistory={imageHistory} 
        onSelectHistoryImage={handleSelectHistoryImage} 
        onPickImage={pickImage} 
        onLoadSaved={loadSavedState}
      />
    </div>
  );
};

